task.spawn(function()
	local env = getgenv()
	local need = {
		"getconnections", "fireclickdetector", "fireproximityprompt", "firetouchinterest", "newcclosure",
		"getrawmetatable", "getnamecallmethod", "setclipboard", "isfolder", "makefolder", "writefile",
