end)
local function uiStub()
	return setmetatable({}, {
		__index = function()
			return function() end
		end,
		__call = function() end,
	})
end
local function guardUI(obj, label)
	if type(obj) ~= "table" then
		return obj
	end
	return setmetatable({}, {
		__index = function(_, k)
			local v = obj[k]
			if type(v) ~= "function" then
				return v
			end
			return function(...)
				local res = table.pack(pcall(v, ...))
				if not res[1] then
					ElevateIdentity()
					res = table.pack(pcall(v, ...))
				end
				if not res[1] then
					warn(("[BananaFix] %s.%s failed: %s"):format(label, tostring(k), tostring(res[2])))
					return uiStub()
				end
				return guardUI(res[2], label .. "." .. tostring(k)), unpack(res, 3, res.n)
			end
		end,
		__newindex = function(_, k, v)
			obj[k] = v
		end,
	})
end

local function readText(inst)
	if not inst then
		return nil
	end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
		return inst.Text ~= "" and inst.Text or nil
	end
	for _, d in ipairs(inst:GetDescendants()) do
		if d:IsA("TextLabel") and d.Text ~= "" then
			return d.Text
		end
	end
	return nil
end
function GetQuestTitle()
	local lp = game:GetService("Players").LocalPlayer
	local pg = lp and lp:FindFirstChild("PlayerGui")
	if not pg then
		return nil
	end
	local main = pg:FindFirstChild("Main") or pg:FindFirstChild("Main (minimal)")
	local q = main and main:FindFirstChild("Quest")
	if q and q.Visible then
		local c = q:FindFirstChild("Container")
		local qt = c and c:FindFirstChild("QuestTitle")
		local txt = readText(qt and qt:FindFirstChild("Title"))
		if txt then
			return txt
		end
	end
	local tr = pg:FindFirstChild("TrackedQuestFrame")
	if tr then
		local on = (tr:IsA("ScreenGui") and tr.Enabled) or (tr:IsA("GuiObject") and tr.Visible)
		local fr = tr:FindFirstChild("Frame")
		if on and fr and fr.Visible then
			return readText(fr:FindFirstChild("header"))
		end
	end
	return nil
end
local _rawHasQuest = function()
	return GetQuestTitle() ~= nil
end
local _questSeenUntil = 0
function HasQuest()
	if _rawHasQuest() then
		_questSeenUntil = tick() + 1
		return true
	end
	return tick() < _questSeenUntil
end

local function collectText(root)
	local out = {}
	if not root then
		return out
	end
	local function add(i)
		if (i:IsA("TextLabel") or i:IsA("TextButton") or i:IsA("TextBox")) and i.Text ~= "" then
			out[#out + 1] = i.Text
		end
	end
	add(root)
	for _, d in ipairs(root:GetDescendants()) do
		add(d)
	end
	return out
end
function GetQuestText()
	local lp = game:GetService("Players").LocalPlayer
	local pg = lp and lp:FindFirstChild("PlayerGui")
	if not pg then
		return ""
	end
	local parts = {}
	local main = pg:FindFirstChild("Main") or pg:FindFirstChild("Main (minimal)")
	local q = main and main:FindFirstChild("Quest")
	if q and q.Visible then
		for _, t in ipairs(collectText(q)) do
			parts[#parts + 1] = t
		end
	end
	local tr = pg:FindFirstChild("TrackedQuestFrame")
	if tr then
		local on = (tr:IsA("ScreenGui") and tr.Enabled) or (tr:IsA("GuiObject") and tr.Visible)
		if on then
			for _, t in ipairs(collectText(tr)) do
				parts[#parts + 1] = t
			end
		end
	end
	return table.concat(parts, " | ")
end
function QuestHas(name)
	if not name then
		return false
	end
	name = tostring(name):lower()
	if GetQuestText():lower():find(name, 1, true) then
		return true
	end
	if GetQuestTitle() and GetQuestTitle():lower():find(name, 1, true) then
		return true
	end
	return false
end
local _lastEliteTake = 0
function EnsureEliteQuest(name)
	if QuestHas(name) then
		return true
	end
	if tick() - _lastEliteTake < 6 then
		return true
	end
	_lastEliteTake = tick()
	local CF = game:GetService("ReplicatedStorage").Remotes.CommF_
	pcall(function()
		if HasQuest() then
			CF:InvokeServer("AbandonQuest")
		end
		CF:InvokeServer("EliteHunter")
	end)
	task.wait(1)
	return QuestHas(name)
end

Settings = {}
HttpService = game:GetService("HttpService")
FolderName = "Windy Hub"
SaveFileNameGame = "-BloxFruitBNNC.json"
SaveFileName = game.Players.LocalPlayer.Name .. SaveFileNameGame
function SaveSettings(b, t, A)
	if A ~= nil then
		Settings[b] = Settings[b] or {}
		Settings[b][t] = A
	elseif b ~= nil then
		Settings[b] = t
	end
	if not isfolder(FolderName) then
		makefolder(FolderName)
	end
	writefile(FolderName .. "/" .. SaveFileName, HttpService:JSONEncode(Settings))
end
if getgenv().Config then
	Settings = getgenv().Config
	SaveSettings()
end
function ReadSetting(tries)
	tries = tries or 0
	local b, t = pcall(function()
		if not isfolder(FolderName) then
			makefolder(FolderName)
		end
		return HttpService:JSONDecode(readfile(FolderName .. "/" .. SaveFileName))
	end)
	if b and type(t) == "table" then
		return t
	else
		if tries >= 3 then
			return {}
		end
		SaveSettings()
		return ReadSetting(tries + 1)
	end
end
Settings = ReadSetting()
getgenv().Settings = Settings
BuyMeleeSecretForce = false
function IsSecretQuestOn()
	return (Settings and Settings["Auto Secret Quest"]) or BuyMeleeSecretForce
end
function IsRepairHold()
	if not (Settings and Settings["Auto Repair Ur Ship"]) then
		return false
	end
	if tick() >= (getgenv().RepairShipHoldUntil or 0) then
		return false
	end
	local c = game:GetService("Players").LocalPlayer.Character
	local hum = c and c:FindFirstChildOfClass("Humanoid")
	return hum ~= nil and not hum.Sit
end
function BuddhaFarmOn()
	return Settings ~= nil
		and Settings["Use Buddha with farming"] == true
		and getgenv().FarmingTabActive == true
		and tick() - (getgenv().BuddhaBossAt or 0) > 1.5
		and not getgenv().BuddhaRemoteHold
end
function TRexAuraOn()
	return Settings ~= nil and Settings["Aura T-rex"] == true
end
function FarmH()
	local h = Settings and tonumber(Settings["Farm Height"])
	if h then
		return math.clamp(h, 1, 200)
	end
	return nil
end
-- 1 = Orbit Farm, 2 = Dung tren dau quai, 3 = Xoay vong quanh quai
function FarmMode()
	local m = Settings and Settings["Farm Mode"]
	if type(m) == "string" then
		local d = m:sub(1, 1)
		if d == "1" or d == "2" or d == "3" then
			return tonumber(d)
		end
	end
	return 2
end
function FarmCF(part, oy)
	local p = part.Position
	local h = FarmH() or oy or 20
	local mode = FarmMode()
	if mode == 2 then
		return CFrame.new(p.X, p.Y + h, p.Z)
	end
	local r, spd
	if mode == 1 then
		r = tonumber(Settings["Orbit Radius"]) or 15
		spd = tonumber(Settings["Orbit Speed"]) or 90
	else
		r = tonumber(Settings["Circle Radius"]) or 6
		spd = tonumber(Settings["Circle Speed"]) or 240
	end
	local a = math.rad((tick() * spd) % 360)
	return CFrame.new(p.X + math.cos(a) * r, p.Y + h, p.Z + math.sin(a) * r)
end
function FruitFarmY()
	return FarmH() or 15
end
function BuddhaFarmY()
	if FarmH() then
		return FarmH()
	end
	if TRexAuraOn() then
		return 15
	end
	-- Buddha V2 has FakeHead; Buddha V1 uses the yellow Body Colors appearance.
	local ch = t and (workspace:FindFirstChild("Characters") and workspace.Characters:FindFirstChild(t.Name) or t.Character)
	if ch then
		if ch:FindFirstChild("FakeHead") then
			return 30
		end
		local bc = ch:FindFirstChild("Body Colors")
		if bc then
			local ok, yellow = pcall(function()
				local function isYellow(c)
					return typeof(c) == "Color3"
						and math.floor(c.R * 255 + 0.5) == 255
						and math.floor(c.G * 255 + 0.5) == 255
						and math.floor(c.B * 255 + 0.5) == 0
				end
				return isYellow(bc.HeadColor3) and isYellow(bc.TorsoColor3)
					and isYellow(bc.LeftArmColor3) and isYellow(bc.RightArmColor3)
					and isYellow(bc.LeftLegColor3) and isYellow(bc.RightLegColor3)
			end)
			if ok and yellow then
				return 20
			end
		end
	end
	return BuddhaFarmOn() and 30 or 20
end
