-- ===================== REDZ LIB (tai thu vien Redz that, noi chuc nang Windy vao) =====================
function __WindyRedzLibUI()
	local CoreGui = game:GetService("CoreGui")
	local lib
	for _, u in ipairs({ "https://pastefy.app/Nm2uyXa3/raw", "https://pastefy.app/wucko9n3/raw" }) do
		local ok, r = pcall(function() return loadstring(game:HttpGet(u))() end)
		if ok and type(r) == "table" and r.MakeWindow then lib = r break end
		task.wait(1)
	end
	if not lib then return nil end

	local function roots()
		local t = { CoreGui }
		if gethui then
			local ok, h = pcall(gethui)
			if ok and h and h ~= CoreGui then t[#t + 1] = h end
		end
		return t
	end
	local function snap()
		local s = {}
		for _, r in ipairs(roots()) do for _, c in ipairs(r:GetChildren()) do s[c] = true end end
		return s
	end
	local function newGuis(before)
		local l = {}
		for _, r in ipairs(roots()) do
			for _, c in ipairs(r:GetChildren()) do
				if not before[c] and c:IsA("ScreenGui") then l[#l + 1] = c end
			end
		end
		return l
	end
	-- logo Windy (nut thu nho)
	local logoAsset = "rbxthumb://type=Asset&id=86158935865051&w=420&h=420"
	pcall(function()
		local b64 = (getgenv().__WindyLogoB64 or ""):gsub("%s", "")
		if #b64 < 100 or not writefile or not getcustomasset then return end
		local raw
		if crypt and crypt.base64decode then raw = crypt.base64decode(b64)
		elseif base64_decode then raw = base64_decode(b64)
		elseif base64 and base64.decode then raw = base64.decode(b64) end
		if raw and #raw > 0 then
			writefile("WindyHub_logo.png", raw)
			local a = getcustomasset("WindyHub_logo.png")
			if a and a ~= "" then logoAsset = a end
		end
	end)

	local before = snap()
	local okW, win = pcall(function()
		return lib:MakeWindow({ Title = "Windy Hub", SubTitle = "Blox Fruits • Việt Hoá", SaveFolder = "WindyHub_Redz.lua" })
	end)
	if not okW or type(win) ~= "table" or not win.MakeTab then return nil end
	pcall(function()
		win:AddMinimizeButton({
			Button = { Image = logoAsset, BackgroundTransparency = 0 },
			Corner = { CornerRadius = UDim.new(0, 5) },
		})
	end)
	local guis = newGuis(before)
	for _, g in ipairs(guis) do pcall(function() g.Enabled = false end) end

	local PREF = { "Farm", "Khu Vực", "Sea Event", "Raid & Fruit", "Race & Items", "Fishing & Quest", "Event", "Halloween", "Player", "Shop", "Setting" }
	local ICONS = {
		["Farm"] = "home", ["Khu Vực"] = "palmtree", ["Sea Event"] = "waves", ["Raid & Fruit"] = "cherry", ["Race & Items"] = "crown",
		["Fishing & Quest"] = "swords", ["Event"] = "Gem", ["Halloween"] = "info", ["Player"] = "user", ["Shop"] = "shopping-cart", ["Setting"] = "settings",
	}
	local function orderOf(name)
		for i, n in ipairs(PREF) do if n == name then return i end end
		return 100
	end
	local tabs, seq = {}, 0
	local built, building = false, false

	local function toSet(t)
		local s = {}
		if type(t) == "table" then
			for k, v in pairs(t) do
				if type(k) == "string" then if v == true then s[k] = true end
				elseif type(v) == "string" then s[v] = true end
			end
		end
		return s
	end

	local function realize(tab, item)
		local o, st, r = item.o, item.st, tab.real
		local kind = item.kind
		if kind == "section" then
			item.real = r:AddSection({ tostring(o) })
		elseif kind == "label" then
			item.real = r:AddParagraph({ Title = "", Desc = st.text })
		elseif kind == "button" then
			item.real = r:AddButton({ Name = o.Name, Description = o.Desc or "", Callback = function() if o.Callback then task.spawn(o.Callback) end end })
		elseif kind == "toggle" then
			item.real = r:AddToggle({
				Name = o.Name, Description = o.Desc or "", Default = st.state,
				Callback = function(v)
					v = v and true or false
					if v ~= st.last then st.last, st.state = v, v if o.Callback then task.spawn(o.Callback, v) end end
				end,
			})
		elseif kind == "slider" then
			item.real = r:AddSlider({
				Name = o.Name, Min = st.min, Max = st.max, Increment = st.step, Default = st.value,
				Callback = function(v)
					v = tonumber(v)
					if v and v ~= st.last then st.last, st.value = v, v if o.Callback then task.spawn(o.Callback, v) end end
				end,
			})
		elseif kind == "dropdown" then
			item.real = r:AddDropdown({
				Name = o.Name, Description = o.Desc or "", Options = st.opts, Default = st.value, MultiSelect = false,
				Callback = function(v)
					if v ~= nil and v ~= st.last then st.last, st.value = v, v if o.Callback then task.spawn(o.Callback, v) end end
				end,
			})
		elseif kind == "multi" then
			item.real = r:AddDropdown({
				Name = o.Name, Description = o.Desc or "", Options = st.opts, Default = st.sel, MultiSelect = true,
				Callback = function(tbl)
					local now = toSet(tbl)
					for n in pairs(now) do
						if not st.sel[n] then
							st.sel[n] = true
							st.ord[#st.ord + 1] = n
							if not st.prio and o.Callback then task.spawn(o.Callback, n, true) end
						end
					end
					for n in pairs(st.sel) do
						if not now[n] then
							st.sel[n] = nil
							for i = #st.ord, 1, -1 do if st.ord[i] == n then table.remove(st.ord, i) end end
							if not st.prio and o.Callback then task.spawn(o.Callback, n, false) end
						end
					end
					if st.prio and o.Callback then task.spawn(o.Callback, table.clone(st.ord)) end
				end,
			})
		elseif kind == "box" then
			item.real = r:AddTextBox({
				Name = o.Name, Description = o.Desc or "", PlaceholderText = o.Placeholder or "", Default = st.text,
				Callback = function(v)
					v = tostring(v or "")
					if o.Numeric then v = v:gsub("[^%d%.%-]", "") end
					st.text = v
					if o.Callback then task.spawn(o.Callback, v) end
				end,
			})
		end
	end
	local function ensureReal(tab)
		if tab.real then return true end
		local ok, rt = pcall(function() return win:MakeTab({ tab.title, ICONS[tab.name] or "info" }) end)
		if ok and rt then tab.real = rt end
		return tab.real ~= nil
	end

	local function makeTab(name, title)
		local tab = { name = name, title = title or name, items = {}, n = 0, curSec = nil }
		seq = seq + 1
		tab.seq = seq
		tabs[#tabs + 1] = tab
		local function add(kind, o, st)
			seq = seq + 1
			local key
			if tab.curSec then tab.curSec.n = tab.curSec.n + 1 key = tab.curSec.rank * 1000 + tab.curSec.n
			else tab.n = tab.n + 1 key = tab.n end
			local item = { kind = kind, o = o, st = st or {}, key = key, seq = seq }
			tab.items[#tab.items + 1] = item
			if built and ensureReal(tab) then pcall(realize, tab, item) end
			return item
		end
		function tab:UseSection(st) tab.curSec = st end
		function tab:AddSection(text) add("section", text) return {} end
		function tab:AddLabel(text)
			local st = { text = tostring(text) }
			local item = add("label", text, st)
			return {
				Set = function(_, t) st.text = tostring(t) if item.real then pcall(function() item.real:SetDesc(st.text) end) end end,
				SetColor = function() end,
				Get = function() return st.text end,
			}
		end
		function tab:AddButton(o) add("button", o) return {} end
		function tab:AddToggle(o)
			local st = { state = o.Default == true }
			st.last = st.state
			local item = add("toggle", o, st)
			if st.state and o.Callback then task.defer(o.Callback, true) end
			local obj = {}
			function obj:Set(v, silent)
				v = v and true or false
				st.state, st.last = v, v
				if item.real then pcall(function() item.real:Set(v) end) end
				if not silent and o.Callback then task.spawn(o.Callback, v) end
			end
			function obj:Get() return st.state end
			return obj
		end
		function tab:AddSlider(o)
			local mn, mx = tonumber(o.Min) or 0, tonumber(o.Max) or 100
			local st = { min = mn, max = mx, step = tonumber(o.Step) or 1, value = math.clamp(tonumber(o.Default) or mn, mn, mx) }
			st.last = st.value
			local item = add("slider", o, st)
			if o.Callback then task.defer(o.Callback, st.value) end
			return {
				Set = function(_, v)
					v = math.clamp(tonumber(v) or st.value, mn, mx)
					st.value, st.last = v, v
					if item.real then pcall(function() item.real:Set(v) end) end
					if o.Callback then task.spawn(o.Callback, v) end
				end,
				Get = function() return st.value end,
			}
		end
		function tab:AddDropdown(o)
			local st = { opts = o.Options or {}, value = o.Default }
			st.last = st.value
			local item = add("dropdown", o, st)
			if st.value ~= nil and o.Callback then task.defer(o.Callback, st.value) end
			return {
				Get = function() return st.value end,
				Set = function(_, v)
					st.value, st.last = v, v
					if item.real then pcall(function() item.real:Set(v) end) end
					if o.Callback then task.spawn(o.Callback, v) end
				end,
				SetOptions = function(_, l)
					st.opts, st.value, st.last = l or {}, nil, nil
					if item.real then
						local ok = pcall(function() item.real:Refresh(st.opts, true) end)
						if not ok then pcall(function() item.real:SetOptions(st.opts) end) end
					end
				end,
			}
		end
		function tab:AddMultiDropdown(o)
			local st = { opts = o.Options or {}, sel = {}, ord = {}, prio = o.Priority == true }
			for _, n in ipairs(o.Init or {}) do
				n = tostring(n)
				if not st.sel[n] then st.sel[n] = true st.ord[#st.ord + 1] = n end
			end
			local item = add("multi", o, st)
			local function push()
				if item.real then pcall(function() item.real:Set(st.sel) end) end
			end
			return {
				SetValue = function(_, v)
					local set = {}
					if type(v) == "table" then
						if #v > 0 then for _, n in ipairs(v) do set[tostring(n)] = true end
						else for n, on in pairs(v) do if on == true then set[tostring(n)] = true end end end
					elseif v ~= nil then set[tostring(v)] = true end
					for n in pairs(set) do
						if not st.sel[n] then
							st.sel[n] = true st.ord[#st.ord + 1] = n
							if not st.prio and o.Callback then task.spawn(o.Callback, n, true) end
						end
					end
					push()
					if st.prio and o.Callback then task.spawn(o.Callback, table.clone(st.ord)) end
				end,
				Refresh = function(_, names, init)
					st.opts, st.sel, st.ord = names or {}, {}, {}
					for _, n in ipairs(init or {}) do
						n = tostring(n)
						st.sel[n] = true st.ord[#st.ord + 1] = n
					end
					if item.real then
						local ok = pcall(function() item.real:Refresh(st.opts, true) end)
						if ok then push() end
					end
				end,
			}
		end
		function tab:AddBox(o)
			local st = { text = o.Default ~= nil and tostring(o.Default) or "" }
			local item = add("box", o, st)
			if st.text ~= "" and o.Callback then task.defer(o.Callback, st.text) end
			return {
				Set = function(_, v)
					st.text = tostring(v)
					if item.real then pcall(function() item.real:Set(st.text) end) end
					if o.Callback then task.spawn(o.Callback, st.text) end
				end,
				Get = function() return st.text end,
			}
		end
		return tab
	end

	local function build()
		if built or building then return end
		building = true
		local list = {}
		for _, t in ipairs(tabs) do list[#list + 1] = t end
		table.sort(list, function(a, b)
			local oa, ob = orderOf(a.name), orderOf(b.name)
			if oa ~= ob then return oa < ob end
			return a.seq < b.seq
		end)
		local t0 = os.clock()
		for _, tab in ipairs(list) do
			if ensureReal(tab) then
				table.sort(tab.items, function(a, b)
					if a.key ~= b.key then return a.key < b.key end
					return a.seq < b.seq
				end)
				for _, item in ipairs(tab.items) do
					local ok, err = pcall(realize, tab, item)
					if not ok then warn("[Windy RedzLib]", item.kind, err) end
					if os.clock() - t0 > 0.012 then task.wait() t0 = os.clock() end
				end
			end
		end
		built, building = true, false
	end

	local function showGuis()
		for _, g in ipairs(guis) do pcall(function() g.Enabled = true end) end
	end
	task.delay(45, showGuis)
	local function isOpen() return guis[1] ~= nil and guis[1].Enabled end
	local function toggle()
		if not isOpen() then
			task.spawn(function()
				local t = os.clock()
				while not built and os.clock() - t < 30 do task.wait(0.1) end
				showGuis()
			end)
		else
			pcall(function() win:Minimize() end)
		end
	end
	return {
		makeTab = makeTab, selectTab = function() end, gui = guis[1] or CoreGui, Flags = {},
		toggle = toggle, isOpen = isOpen, setOpen = function(v) if v and not isOpen() then toggle() end end,
		accent = function() return Color3.fromRGB(146, 208, 236) end,
		logoAsset = logoAsset,
		Build = build,
	}
end

function __WindyRedzUI()
------------------------------------------------------------------ WINDY x REDZ UI (nen trong suot, nut den)
local Players = game:GetService("Players")
local UIS = game:GetService("UserInputService")
local TS = game:GetService("TweenService")
local CoreGui = game:GetService("CoreGui")
local Lighting = game:GetService("Lighting")
local lp = Players.LocalPlayer
getgenv().__WindyLoaded = false

local C = {
	glass = Color3.fromRGB(8, 8, 12), glassT = 0.3,
	black = Color3.fromRGB(0, 0, 0), cardT = 0.16,
	line = Color3.fromRGB(88, 24, 32),
	accent = Color3.fromRGB(235, 42, 62),
	text = Color3.fromRGB(242, 242, 248), mut = Color3.fromRGB(150, 152, 168),
}
local function new(cls, props, kids)
	local o = Instance.new(cls)
	for k, v in pairs(props or {}) do if k ~= "Parent" then o[k] = v end end
	for _, c in ipairs(kids or {}) do c.Parent = o end
	if props and props.Parent then o.Parent = props.Parent end
	return o
end
local function corner(r) return new("UICorner", { CornerRadius = UDim.new(0, r) }) end
local function stroke(col, th, tr)
	return new("UIStroke", { Color = col or C.line, Thickness = th or 1, Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end
local function isPress(i) return i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch end
local function isMove(i) return i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch end
local function txt(parent, str, size, font, color, pos, sz, xa)
	return new("TextLabel", {
		Parent = parent, BackgroundTransparency = 1, Text = str, TextSize = size, Font = font, TextColor3 = color,
		Position = pos or UDim2.new(), Size = sz or UDim2.new(1, 0, 1, 0), TextXAlignment = xa or Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
end

local parentGui = (function()
	if gethui then
		local ok, h = pcall(gethui)
		if ok and h then return h end
	end
	local ok = pcall(function() return CoreGui.Name end)
	if ok then return CoreGui end
	return lp:WaitForChild("PlayerGui")
end)()
for _, n in ipairs({ "WindyHubUI", "WindyIntro" }) do
	local old = parentGui:FindFirstChild(n)
	if old then old:Destroy() end
end
pcall(function() local b = Lighting:FindFirstChild("WindyBlur") if b then b:Destroy() end end)

local gui = new("ScreenGui", { Name = "WindyHubUI", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 200, ZIndexBehavior = Enum.ZIndexBehavior.Sibling })
pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
gui.Parent = parentGui

local holder = new("Frame", { Parent = gui, BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 0, 0, 0) })
local main = new("Frame", {
	Parent = holder, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(), Size = UDim2.new(0, 660, 0, 410),
	BackgroundColor3 = C.glass, BackgroundTransparency = C.glassT, BorderSizePixel = 0,
}, { corner(14) })
local mainStroke = stroke(C.accent, 1.2, 0.45)
mainStroke.Parent = main
new("UIGradient", {
	Parent = main, Rotation = 90,
	Color = ColorSequence.new(Color3.fromRGB(18, 14, 20), Color3.fromRGB(2, 2, 4)),
	Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.15) }),
})
local uiScale = new("UIScale", { Parent = main })
local userMul, baseScale = 1, 1
local function applyScale() uiScale.Scale = baseScale * userMul end
local function fitScale()
	local cam = workspace.CurrentCamera
	if not cam then return end
	local v = cam.ViewportSize
	baseScale = math.clamp(math.min(v.X / 700, v.Y / 450), 0.45, 1)
	applyScale()
end
fitScale()
if workspace.CurrentCamera then workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fitScale) end

-- logo Windy
local B64 = getgenv().__WindyLogoB64 or ""
local logoImg, floatImg
local function dec(data)
	local ok, r = pcall(function()
		if crypt and crypt.base64decode then return crypt.base64decode(data) end
		if base64_decode then return base64_decode(data) end
		if base64 and base64.decode then return base64.decode(data) end
		error("no")
	end)
	if ok and r and #r > 0 then return r end
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, 64 do map[chars:sub(i, i)] = i - 1 end
	data = data:gsub("[^%w%+/=]", "")
	local out, n = {}, 0
	for i = 1, #data, 4 do
		local a, b, c, d = map[data:sub(i, i)], map[data:sub(i + 1, i + 1)], map[data:sub(i + 2, i + 2)], map[data:sub(i + 3, i + 3)]
		if not a or not b then break end
		local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
		n = n + 1 out[n] = string.char(math.floor(v / 65536) % 256)
		if c then n = n + 1 out[n] = string.char(math.floor(v / 256) % 256) end
		if d then n = n + 1 out[n] = string.char(v % 256) end
	end
	return table.concat(out)
end

