------------------------------------------------------------------ KEO CUA SO
local function makeDraggable(handle, target, onClick)
	local dragging, startPos, origin, moved
	handle.InputBegan:Connect(function(i)
		if isPress(i) then
			dragging, startPos, origin, moved = true, i.Position, target.Position, false
			i.Changed:Connect(function()
				if i.UserInputState == Enum.UserInputState.End then
					dragging = false
					if onClick and not moved then onClick() end
				end
			end)
		end
	end)
	UIS.InputChanged:Connect(function(i)
		if dragging and isMove(i) then
			local d = i.Position - startPos
			if d.Magnitude > 6 then moved = true end
			if moved then target.Position = UDim2.new(origin.X.Scale, origin.X.Offset + d.X, origin.Y.Scale, origin.Y.Offset + d.Y) end
		end
	end)
end
makeDraggable(topbar, holder)

------------------------------------------------------------------ TAB
local tabs, activeTab, userPicked = {}, nil, false
local PREF = { "Farm", "Khu Vực", "Sea Event", "Raid & Fruit", "Race & Items", "Fishing & Quest", "Event", "Halloween", "Player", "Shop", "Setting" }
local function orderOf(name)
	for i, n in ipairs(PREF) do if n == name then return i end end
	return 100 + #tabs
end
local function selectTab(t)
	for _, x in ipairs(tabs) do
		local on = (x == t)
		x.page.Visible = on
		x.bar.Visible = on
		x.lab.TextColor3 = on and C.text or C.mut
		TS:Create(x.bs, TweenInfo.new(0.15), { Transparency = on and 0 or 0.6, Color = on and C.accent or C.line }):Play()
		x.active = on
	end
	activeTab = t
end

local function makeTab(name, title)
	local tab = { name = name, active = false }
	local btn = new("TextButton", {
		Parent = sidebar, AutoButtonColor = false, Text = "", Size = UDim2.new(1, 0, 0, 38), BackgroundColor3 = C.black,
		BackgroundTransparency = C.cardT, BorderSizePixel = 0, LayoutOrder = orderOf(name),
	}, { corner(8) })
	tab.bs = stroke(C.line, 1, 0.6)
	tab.bs.Parent = btn
	tab.bar = new("Frame", { Parent = btn, Position = UDim2.new(0, 0, 0.5, -9), Size = UDim2.new(0, 3, 0, 18), BackgroundColor3 = C.accent, BorderSizePixel = 0, Visible = false }, { corner(2) })
	local ic = new("Frame", { Parent = btn, Position = UDim2.new(0, 10, 0.5, -11), Size = UDim2.new(0, 22, 0, 22), BackgroundColor3 = C.black, BorderSizePixel = 0 }, { corner(6), stroke(C.accent, 1, 0.5) })
	txt(ic, string.upper(string.sub(name, 1, 1)), 12, Enum.Font.GothamBold, C.accent, UDim2.new(), UDim2.new(1, 0, 1, 0), Enum.TextXAlignment.Center)
	tab.lab = txt(btn, name, 13, Enum.Font.GothamMedium, C.mut, UDim2.new(0, 40, 0, 0), UDim2.new(1, -46, 1, 0))
	tab.btn = btn

	local scroll = new("ScrollingFrame", {
		Parent = pages, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0), Visible = false,
		ScrollBarThickness = 3, ScrollBarImageColor3 = C.accent, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
	})
	new("UIListLayout", { Parent = scroll, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder })
	new("UIPadding", { Parent = scroll, PaddingRight = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6) })
	tab.page = scroll
	local head = txt(scroll, title or name, 18, Enum.Font.GothamBold, C.text, UDim2.new(), UDim2.new(1, 0, 0, 28))
	head.LayoutOrder = -1

	local order, current = 0, nil
	local function nextOrder()
		if current then current.n = current.n + 1 return current.rank * 1000 + current.n end
		order = order + 1
		return order
	end
	function tab:UseSection(st) current = st end

	btn.MouseButton1Click:Connect(function() userPicked = true selectTab(tab) end)
	tabs[#tabs + 1] = tab
	if not userPicked then
		local best = tabs[1]
		for _, x in ipairs(tabs) do if x.btn.LayoutOrder < best.btn.LayoutOrder then best = x end end
		selectTab(best)
	end

	local function card(h)
		return new("Frame", { Parent = scroll, Size = UDim2.new(1, 0, 0, h), BackgroundColor3 = C.black, BackgroundTransparency = C.cardT, BorderSizePixel = 0, LayoutOrder = nextOrder() }, { corner(8), stroke(C.line, 1, 0.25) })
	end
	local function nameDesc(f, o, wRight)
		local hasD = o.Desc ~= nil and o.Desc ~= ""
		txt(f, o.Name, 13, Enum.Font.GothamMedium, C.text, UDim2.new(0, 12, 0, hasD and 7 or 0), UDim2.new(1, -wRight, 0, hasD and 16 or f.Size.Y.Offset))
		if hasD then txt(f, o.Desc, 11, Enum.Font.Gotham, C.mut, UDim2.new(0, 12, 0, 25), UDim2.new(1, -wRight, 0, 14)) end
	end

	function tab:AddSection(text)
		local f = new("Frame", { Parent = scroll, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = nextOrder() })
		new("Frame", { Parent = f, Position = UDim2.new(0, 0, 0.5, -6), Size = UDim2.new(0, 3, 0, 12), BackgroundColor3 = C.accent, BorderSizePixel = 0 }, { corner(2) })
		return txt(f, string.upper(text), 11, Enum.Font.GothamBold, C.accent, UDim2.new(0, 10, 0, 0), UDim2.new(1, -10, 1, 0))
	end

	function tab:AddLabel(text)
		local f = card(34)
		local l = txt(f, text, 12, Enum.Font.Gotham, C.mut, UDim2.new(0, 12, 0, 0), UDim2.new(1, -24, 1, 0))
		return { Set = function(_, t) l.Text = tostring(t) end, SetColor = function(_, c) if typeof(c) == "Color3" then l.TextColor3 = c end end, Get = function() return l.Text end }
	end

	function tab:AddToggle(o)
		local f = card(o.Desc and 48 or 40)
		nameDesc(f, o, 70)
		local box = new("TextButton", {
			Parent = f, AutoButtonColor = false, Text = "", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.new(0, 26, 0, 26),
			BackgroundColor3 = C.black, BorderSizePixel = 0,
		}, { corner(7) })
		local bst = stroke(C.line, 1.4, 0)
		bst.Parent = box
		local dot = new("Frame", { Parent = box, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(0, 0, 0, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0 }, { corner(4) })
		local state = o.Default == true
		local function visual(anim)
			local ti = TweenInfo.new(anim and 0.16 or 0, Enum.EasingStyle.Quad)
			TS:Create(dot, ti, { Size = state and UDim2.new(0, 14, 0, 14) or UDim2.new(0, 0, 0, 0) }):Play()
			TS:Create(bst, ti, { Color = state and C.accent or C.line }):Play()
		end
		visual(false)
		local obj = {}
		local function set(v, silent)
			state = v and true or false
			visual(true)
			if not silent and o.Callback then task.spawn(o.Callback, state) end
		end
		box.MouseButton1Click:Connect(function() set(not state) end)
		local hit = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, -44, 1, 0), ZIndex = 2 })
		hit.MouseButton1Click:Connect(function() set(not state) end)
		if state and o.Callback then task.defer(o.Callback, state) end
		function obj:Set(v, silent) set(v, silent) end
		function obj:Get() return state end
		return obj
	end

	function tab:AddSlider(o)
		local f = card(56)
		txt(f, o.Name, 13, Enum.Font.GothamMedium, C.text, UDim2.new(0, 12, 0, 6), UDim2.new(0.62, 0, 0, 18))
		local valL = txt(f, "", 12, Enum.Font.GothamBold, C.accent, UDim2.new(0.62, 0, 0, 6), UDim2.new(0.38, -12, 0, 18), Enum.TextXAlignment.Right)
		local track = new("Frame", { Parent = f, Position = UDim2.new(0, 12, 0, 36), Size = UDim2.new(1, -24, 0, 6), BackgroundColor3 = C.black, BorderSizePixel = 0 }, { corner(3), stroke(C.line, 1, 0.2) })
		local fill = new("Frame", { Parent = track, Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = C.accent, BorderSizePixel = 0 }, { corner(3) })
		local knob = new("Frame", { Parent = track, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0, 14, 0, 14), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 3 }, { corner(7), stroke(C.accent, 1.5, 0) })
		local minV, maxV, step = tonumber(o.Min) or 0, tonumber(o.Max) or 100, tonumber(o.Step) or 1
		local value = math.clamp(tonumber(o.Default) or minV, minV, maxV)
		local dragging = false
		local function render()
			local a = (value - minV) / math.max(maxV - minV, 1e-9)
			fill.Size = UDim2.new(a, 0, 1, 0)
			knob.Position = UDim2.new(a, 0, 0.5, 0)
			valL.Text = tostring(value)
		end
		local function set(v, silent)
			v = math.clamp(v, minV, maxV)
			v = math.floor(v / step + 0.5) * step
			if step < 1 then v = math.floor(v * 100 + 0.5) / 100 end
			v = math.clamp(v, minV, maxV)
			if v == value and not silent then return end
			value = v
			render()
			if not silent and o.Callback then task.spawn(o.Callback, value) end
		end
		local function fromX(x)
			local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
			set(minV + (maxV - minV) * a)
		end
		local hit = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Position = UDim2.new(0, 0, 0, 26), Size = UDim2.new(1, 0, 0, 30), ZIndex = 2 })
		hit.InputBegan:Connect(function(i) if isPress(i) then dragging = true fromX(i.Position.X) end end)
		UIS.InputChanged:Connect(function(i) if dragging and isMove(i) then fromX(i.Position.X) end end)
		UIS.InputEnded:Connect(function(i) if isPress(i) then dragging = false end end)
		render()
		if o.Callback then task.defer(o.Callback, value) end
		return { Set = function(_, v) set(v) end, Get = function() return value end }
	end

	function tab:AddButton(o)
		local f = card(o.Desc and 48 or 40)
		nameDesc(f, o, 90)
		local pill = new("Frame", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.new(0, 60, 0, 26), BackgroundColor3 = C.black, BorderSizePixel = 0 }, { corner(7) })
		local pst = stroke(C.accent, 1.2, 0.2)
		pst.Parent = pill
		txt(pill, "Nhấn", 12, Enum.Font.GothamBold, C.accent, UDim2.new(), UDim2.new(1, 0, 1, 0), Enum.TextXAlignment.Center)
		local hit = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 1, 0), ZIndex = 2 })
		hit.MouseButton1Click:Connect(function()
			TS:Create(pill, TweenInfo.new(0.08), { BackgroundColor3 = C.accent }):Play()
			task.delay(0.12, function() TS:Create(pill, TweenInfo.new(0.2), { BackgroundColor3 = C.black }):Play() end)
			if o.Callback then task.spawn(o.Callback) end
		end)
		return {}
	end

	function tab:AddDropdown(o)
		local opts = o.Options or {}
		local current = o.Default
		local f = card(42)
		f.ClipsDescendants = true
		txt(f, o.Name, 13, Enum.Font.GothamMedium, C.text, UDim2.new(0, 12, 0, 0), UDim2.new(0.5, 0, 0, 42))
		local headBtn = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 0, 42), ZIndex = 2 })
		local cur = txt(headBtn, "", 12, Enum.Font.GothamMedium, C.accent, UDim2.new(0.5, 0, 0, 0), UDim2.new(0.5, -34, 1, 0), Enum.TextXAlignment.Right)
		local chev = txt(headBtn, "v", 12, Enum.Font.GothamBold, C.accent, UDim2.new(1, -26, 0, 0), UDim2.new(0, 16, 1, 0), Enum.TextXAlignment.Center)
		local list = new("Frame", { Parent = f, BackgroundTransparency = 1, Position = UDim2.new(0, 8, 0, 46), Size = UDim2.new(1, -16, 0, 0) })
		new("UIListLayout", { Parent = list, Padding = UDim.new(0, 3) })
		local open = false
		local function refresh()
			cur.Text = (current ~= nil and tostring(current) or "Chọn...")
			chev.Rotation = open and 180 or 0
		end
		local function resize() f.Size = UDim2.new(1, 0, 0, open and (50 + #opts * 30) or 42) end
		local function pick(op, silent)
			current = op
			open = false
			resize()
			refresh()
			if not silent and o.Callback then task.spawn(o.Callback, current) end
		end
		local function rebuild()
			for _, c in ipairs(list:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
			for _, op in ipairs(opts) do
				local b = new("TextButton", {
					Parent = list, AutoButtonColor = false, Text = tostring(op), Font = Enum.Font.Gotham, TextSize = 12, TextColor3 = C.text,
					Size = UDim2.new(1, 0, 0, 27), BackgroundColor3 = C.black, BackgroundTransparency = 0.05, BorderSizePixel = 0,
				}, { corner(6), stroke(C.line, 1, 0.45) })
				b.MouseButton1Click:Connect(function() pick(op) end)
			end
			list.Size = UDim2.new(1, -16, 0, #opts * 30)
			if open then resize() end
		end
		headBtn.MouseButton1Click:Connect(function() open = not open resize() refresh() end)
		rebuild()
		refresh()
		if current ~= nil and o.Callback then task.defer(o.Callback, current) end
		return {
			Get = function() return current end,
			Set = function(_, v) pick(v) end,
			SetOptions = function(_, l) opts = l or {} current = nil rebuild() refresh() end,
		}
	end

	function tab:AddMultiDropdown(o)
		local prio = o.Priority == true
		local opts, sel, ord, rows = {}, {}, {}, {}
		local f = card(42)
		f.ClipsDescendants = true
		txt(f, o.Name, 13, Enum.Font.GothamMedium, C.text, UDim2.new(0, 12, 0, 0), UDim2.new(0.45, 0, 0, 42))
		local headBtn = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 0, 42), ZIndex = 2 })
		local cur = txt(headBtn, "", 12, Enum.Font.GothamMedium, C.accent, UDim2.new(0.45, 0, 0, 0), UDim2.new(0.55, -34, 1, 0), Enum.TextXAlignment.Right)
		local chev = txt(headBtn, "v", 12, Enum.Font.GothamBold, C.accent, UDim2.new(1, -26, 0, 0), UDim2.new(0, 16, 1, 0), Enum.TextXAlignment.Center)
		local list = new("Frame", { Parent = f, BackgroundTransparency = 1, Position = UDim2.new(0, 8, 0, 46), Size = UDim2.new(1, -16, 0, 0) })
		new("UIListLayout", { Parent = list, Padding = UDim.new(0, 3) })
		local open = false
		local function summary()
			if prio then return #ord > 0 and table.concat(ord, " > ") or "Chọn..." end
			local n = 0
			for _, v in pairs(sel) do if v then n = n + 1 end end
			return n > 0 and (n .. " đã chọn") or "Chọn..."
		end
		local function resize() f.Size = UDim2.new(1, 0, 0, open and (50 + #opts * 30) or 42) end
		local function refresh()
			cur.Text = summary()
			chev.Rotation = open and 180 or 0
			for n, r in pairs(rows) do r.Visible = sel[n] and true or false end
		end
		local function toggle(name, on, silent)
			on = on and true or false
			sel[name] = on
			if prio then
				for i = #ord, 1, -1 do if ord[i] == name then table.remove(ord, i) end end
				if on then ord[#ord + 1] = name end
			end
			refresh()
			if not silent and o.Callback then
				if prio then task.spawn(o.Callback, table.clone(ord)) else task.spawn(o.Callback, name, on) end
			end
		end
		local function build(names)
			for _, c in ipairs(list:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
			opts, sel, ord, rows = names, {}, {}, {}
			for _, n in ipairs(names) do
				local b = new("TextButton", {
					Parent = list, AutoButtonColor = false, Text = "", Size = UDim2.new(1, 0, 0, 27), BackgroundColor3 = C.black, BackgroundTransparency = 0.05, BorderSizePixel = 0,
				}, { corner(6), stroke(C.line, 1, 0.45) })
				txt(b, n, 12, Enum.Font.Gotham, C.text, UDim2.new(0, 10, 0, 0), UDim2.new(1, -40, 1, 0))
				local ck = new("Frame", { Parent = b, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.new(0, 12, 0, 12), BackgroundColor3 = C.accent, BorderSizePixel = 0, Visible = false }, { corner(3) })
				rows[n] = ck
				b.MouseButton1Click:Connect(function() toggle(n, not sel[n]) end)
			end
			list.Size = UDim2.new(1, -16, 0, #names * 30)
			if open then resize() end
			refresh()
		end
		headBtn.MouseButton1Click:Connect(function() open = not open resize() refresh() end)
		build(o.Options or {})
		for _, n in ipairs(o.Init or {}) do if rows[n] then toggle(n, true) end end
		return {
			SetValue = function(_, v)
				if type(v) == "table" then
					if #v > 0 then for _, n in ipairs(v) do if rows[tostring(n)] then toggle(tostring(n), true) end end
					else for n, on in pairs(v) do if on == true and rows[tostring(n)] then toggle(tostring(n), true) end end end
				elseif v ~= nil and rows[tostring(v)] then toggle(tostring(v), true) end
			end,
			Refresh = function(_, names, init)
				build(names)
				for _, n in ipairs(init or {}) do if rows[n] then toggle(n, true) end end
			end,
		}
	end

	function tab:AddBox(o)
		local f = card(42)
		txt(f, o.Name, 13, Enum.Font.GothamMedium, C.text, UDim2.new(0, 12, 0, 0), UDim2.new(0.4, 0, 1, 0))
		local tb = new("TextBox", {
			Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.new(0.5, 0, 0, 28),
			Text = o.Default ~= nil and tostring(o.Default) or "", PlaceholderText = o.Placeholder or "", ClearTextOnFocus = false,
			Font = Enum.Font.Gotham, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = C.text, PlaceholderColor3 = C.mut,
			BackgroundColor3 = C.black, BorderSizePixel = 0,
		}, { corner(7), stroke(C.accent, 1, 0.5), new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }) })
		local function fireCb() if o.Callback then task.spawn(o.Callback, tb.Text) end end
		tb.FocusLost:Connect(function()
			if o.Numeric then tb.Text = tb.Text:gsub("[^%d%.%-]", "") end
			fireCb()
		end)
		if tb.Text ~= "" and o.Callback then task.defer(o.Callback, tb.Text) end
		return { Set = function(_, v) tb.Text = tostring(v) fireCb() end, Get = function() return tb.Text end }
	end

	return tab
end

