local function blurTo(sz) if blur then TS:Create(blur, TweenInfo.new(0.35, Enum.EasingStyle.Quad), { Size = sz }):Play() end end
gui.Destroying:Connect(function() if blur then pcall(function() blur:Destroy() end) end end)

local WS = { open = true, tok = 0, moving = false, rest = holder.Position, tw = {} }
local function offPos(p) return UDim2.new(p.X.Scale, p.X.Offset, p.Y.Scale + 1, p.Y.Offset + 160) end
local function showWindow(v)
	v = v and true or false
	if v == WS.open then return end
	WS.open = v
	WS.tok = WS.tok + 1
	local tok = WS.tok
	for _, t in ipairs(WS.tw) do pcall(function() t:Cancel() end) end
	WS.tw = {}
	local full = baseScale * userMul
	local function mk(o, ti, props) local t = TS:Create(o, ti, props) WS.tw[#WS.tw + 1] = t return t end
	if v then
		if not WS.moving then holder.Position = offPos(WS.rest) uiScale.Scale = full * 0.86 end
		WS.moving = true
		holder.Visible = true
		blurTo(12)
		local a = mk(holder, TweenInfo.new(0.46, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Position = WS.rest })
		local b = mk(uiScale, TweenInfo.new(0.55, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = full })
		a.Completed:Connect(function(st)
			if tok == WS.tok and st == Enum.PlaybackState.Completed then WS.moving = false applyScale() end
		end)
		a:Play() b:Play()
	else
		if not WS.moving then WS.rest = holder.Position end
		WS.moving = true
		blurTo(0)
		local a = mk(holder, TweenInfo.new(0.36, Enum.EasingStyle.Quint, Enum.EasingDirection.In), { Position = offPos(WS.rest) })
		local b = mk(uiScale, TweenInfo.new(0.36, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = full * 0.88 })
		a.Completed:Connect(function(st)
			if tok == WS.tok and st == Enum.PlaybackState.Completed then
				WS.moving = false
				holder.Visible = false
				holder.Position = WS.rest
				applyScale()
			end
		end)
		a:Play() b:Play()
	end
end
btnMin.MouseButton1Click:Connect(function() showWindow(false) end)
btnClose.MouseButton1Click:Connect(function() gui:Destroy() end)
makeDraggable(floatBtn, floatBtn, function() showWindow(not WS.open) end)
UIS.InputBegan:Connect(function(i, gp)
	if not gp and i.KeyCode == Enum.KeyCode.LeftControl then showWindow(not WS.open) end
end)
