-- ---------- drag muot ----------
local function makeDrag(handle, target, o)
	o = o or {}
	local pressed, dragging, dragInput, dragStart = false, false, nil, nil
	local sx, sy, ox, oy, gx, gy, cx, cy = 0, 0, 0, 0, 0, 0, 0, 0
	local conn
	local function bounds() local a = gui.AbsoluteSize return a.X, a.Y end
	local function clampOff(x, y)
		if not o.clamp then return x, y end
		local W, H = bounds()
		if W <= 0 or H <= 0 then return x, y end
		local bw, bh = target.AbsoluteSize.X, target.AbsoluteSize.Y
		local ax = math.clamp(sx * W + x, 0, math.max(W - bw, 0))
		local ay = math.clamp(sy * H + y, 0, math.max(H - bh, 0))
		return ax - sx * W, ay - sy * H
	end
	local function stop() if conn then conn:Disconnect() conn = nil end end
	local function step(dt)
		if pressed and dragInput and dragStart then
			local d = dragInput.Position - dragStart
			if not dragging and d.Magnitude > 6 then dragging = true end
			if dragging then gx, gy = clampOff(ox + d.X, oy + d.Y) end
		end
		local a = 1 - math.exp(-dt * 20)
		cx = cx + (gx - cx) * a
		cy = cy + (gy - cy) * a
		target.Position = UDim2.new(sx, cx, sy, cy)
		if not pressed and math.abs(gx - cx) < 0.4 and math.abs(gy - cy) < 0.4 then
			target.Position = UDim2.new(sx, gx, sy, gy)
			stop()
		end
	end
	handle.InputBegan:Connect(function(input)
		if not isPress(input) then return end
		pressed, dragging, dragStart, dragInput = true, false, input.Position, input
		local p = target.Position
		sx, sy, ox, oy = p.X.Scale, p.Y.Scale, p.X.Offset, p.Y.Offset
		cx, cy, gx, gy = ox, oy, ox, oy
		if not conn then conn = RunService.RenderStepped:Connect(step) end
		input.Changed:Connect(function()
			if input.UserInputState ~= Enum.UserInputState.End then return end
			pressed = false
			if dragging then
				dragging = false
				if o.snap then
					local W = bounds()
					local bw = target.AbsoluteSize.X
					if W > 0 then
						local centerX = sx * W + gx + bw / 2
						local tx = (centerX < W / 2) and 10 or (W - bw - 10)
						gx, gy = clampOff(tx - sx * W, gy)
					end
				end
			elseif o.onClick then
				task.spawn(o.onClick)
			end
		end)
	end)
	UIS.InputChanged:Connect(function(input)
		if pressed and isMove(input) then dragInput = input end
	end)
end

