local function openPopup(btn, options, isSel, onPick, multi)
	closePopup()
	local overlay = new("TextButton", { Parent = gui, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 1, 0), ZIndex = 300, AutoButtonColor = false })
