	local w = math.max(btn.AbsoluteSize.X / s, 132)
	local f = new("Frame", { Parent = overlay, BackgroundColor3 = COL.card, BorderSizePixel = 0, ZIndex = 301 }, { corner(10), stroke(accent, 1, 0.5) })
	local ps = btn.AbsolutePosition
	local py = ps.Y + btn.AbsoluteSize.Y + 4
