	f.Position = UDim2.fromOffset(px, py)
	new("UIScale", { Parent = f, Scale = s })
	f.Size = UDim2.fromOffset(w, h)
	local list = new("ScrollingFrame", { Parent = f, BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.new(0, 5, 0, 5), Size = UDim2.new(1, -10, 1, -10), ScrollBarThickness = 2, ScrollBarImageColor3 = accent, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 302 })
	new("UIListLayout", { Parent = list, Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder })
	for i, op in ipairs(options) do
		local name = tostring(op)
		local b = new("TextButton", { Parent = list, Size = UDim2.new(1, -4, 0, rowH), BackgroundColor3 = COL.hover, BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = i, ZIndex = 303 }, { corner(7) })
		local l = txt(b, name, 11, Enum.Font.GothamMedium, isSel(name) and accent or COL.text, UDim2.new(0, 10, 0, 0), UDim2.new(1, -30, 1, 0))
		l.ZIndex = 304
		local ck = new("Frame", { Parent = b, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -9, 0.5, 0), Size = UDim2.fromOffset(multi and 12 or 6, multi and 12 or 6), BackgroundColor3 = accent, BorderSizePixel = 0, Visible = isSel(name), ZIndex = 304 }, { corner(3) })
		b.MouseEnter:Connect(function() TS:Create(b, TweenInfo.new(0.1), { BackgroundTransparency = 0 }):Play() end)
		b.MouseLeave:Connect(function() TS:Create(b, TweenInfo.new(0.1), { BackgroundTransparency = 1 }):Play() end)
		b.MouseButton1Click:Connect(function()
			onPick(name)
			if multi then
				local on = isSel(name)
				ck.Visible = on
				l.TextColor3 = on and accent or COL.text
			else
				closePopup()
			end
		end)
	end
end

-- ---------- glyph ----------
local function glyph(parent, seed, col)
	local n = 0
	for i = 1, #seed do n = n + seed:byte(i) end
	local k = n % 5
	col = col or COL.mut
	local function base(sz, extra)
		extra = extra or {}
		extra.Parent = parent extra.AnchorPoint = Vector2.new(0.5, 0.5) extra.Position = UDim2.new(0.5, 0, 0.5, 0) extra.Size = sz
		return extra
	end
	if k == 0 then return new("Frame", base(UDim2.fromOffset(10, 10), { BackgroundTransparency = 1 }), { corner(5), stroke(col, 1.5, 0) })
	elseif k == 1 then return new("Frame", base(UDim2.fromOffset(9, 9), { BackgroundTransparency = 1, Rotation = 45 }), { corner(2), stroke(col, 1.5, 0) })
	elseif k == 2 then return new("Frame", base(UDim2.fromOffset(10, 10), { BackgroundTransparency = 1 }), { corner(3), stroke(col, 1.5, 0) })
	elseif k == 3 then return new("Frame", base(UDim2.fromOffset(6, 6), { BackgroundColor3 = col, BorderSizePixel = 0 }), { corner(3) })
	end
	return new("Frame", base(UDim2.fromOffset(11, 2), { BackgroundColor3 = col, BorderSizePixel = 0 }), { corner(1) })
end

