local function runPending(tab)
	if tab.realized or tab.realizing then return end
	tab.realizing = true
	task.spawn(function()
		local t0 = os.clock()
		local i = 1
		while i <= #tab.pending do
			local ok, err = pcall(tab.pending[i])
			if not ok then warn("[Windy UI]", err) end
			i = i + 1
			if os.clock() - t0 > 0.012 then task.wait() t0 = os.clock() end
		end
		tab.pending = {}
		tab.realized = true
	end)
end
local function applyTabSearch()
	local q = string.lower(tabSearch.Text or "")
	if not current then return end
	if q ~= "" then runPending(current) end
	for _, r in ipairs(current.rows) do
		local hay = string.lower((r.t and r.t.Text or "") .. " " .. (r.d and r.d.Text or ""))
		r.f.Visible = (q == "") or (string.find(hay, q, 1, true) ~= nil)
	end
	for _, h in ipairs(current.heads) do h.Visible = (q == "") end
end
tabSearch:GetPropertyChangedSignal("Text"):Connect(applyTabSearch)
openTab = function(tab)
	closePopup()
	current = tab
	tabSearch.Text = ""
	for _, t in ipairs(tabs) do t.scroll.Visible = (t == tab) end
	pageTitle.Text = tab.title
	runPending(tab)
	applyTabSearch()
	showPage("cat")
end

local function makeTab(name, title)
	local tab = { name = name, title = title or name, pending = {}, rows = {}, heads = {}, realized = false }
	-- the trong luoi
	local card = new("TextButton", { Parent = grid, BackgroundColor3 = COL.card, Text = "", AutoButtonColor = false, LayoutOrder = orderOf(name) }, { corner(12), stroke(accent, 1, 0.6) })
	themed[#themed + 1] = { card:FindFirstChildOfClass("UIStroke"), "Color", "accent" }
	cardGrad(card, true)
	local ib = new("Frame", { Parent = card, Position = UDim2.new(0, 11, 0.5, -15), Size = UDim2.fromOffset(30, 30), BackgroundColor3 = accent, BorderSizePixel = 0 }, { corner(9) })
	bind(ib, "BackgroundColor3", "dim")
	glyph(ib, name, accent)
	txt(card, title or name, 10, Enum.Font.GothamBlack, COL.text, UDim2.new(0, 52, 0, 12), UDim2.new(1, -78, 0, 16))
	local sd = txt(card, SUBS[name] or "", 8, Enum.Font.Gotham, COL.mut, UDim2.new(0, 52, 0, 30), UDim2.new(1, -62, 0, 14))
	tab.num = txt(card, "00", 7, Enum.Font.GothamBold, COL.mut, UDim2.new(1, -30, 0, 6), UDim2.new(0, 22, 0, 10), Enum.TextXAlignment.Right)
	tab.btn = card
	card.MouseEnter:Connect(function() TS:Create(card, TweenInfo.new(0.15), { Size = UDim2.fromOffset(200, 60) }):Play() end)
	card.MouseLeave:Connect(function() TS:Create(card, TweenInfo.new(0.15), { Size = UDim2.fromOffset(196, 58) }):Play() end)
	card.MouseButton1Click:Connect(function() openTab(tab) end)

	local scroll = new("ScrollingFrame", {
		Parent = pages, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0), Visible = false,
		ScrollBarThickness = 3, ScrollBarImageColor3 = accent, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
	})
	themed[#themed + 1] = { scroll, "ScrollBarImageColor3", "accent" }
	new("UIListLayout", { Parent = scroll, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder })
	new("UIPadding", { Parent = scroll, PaddingRight = UDim.new(0, 8), PaddingBottom = UDim.new(0, 8), PaddingLeft = UDim.new(0, 4) })
	tab.scroll = scroll
	tabs[#tabs + 1] = tab
	renumber()

	local order, curSec = 0, nil
	local function nextOrder()
		if curSec then curSec.n = curSec.n + 1 return curSec.rank * 1000 + curSec.n end
		order = order + 1
		return order
	end
	local function build(fn)
		if tab.realized then
			local ok, err = pcall(fn)
			if not ok then warn("[Windy UI]", err) end
		else
			tab.pending[#tab.pending + 1] = fn
		end
	end
	local function reg(o) entries[#entries + 1] = { tab = tab, name = o.Name, desc = o.Desc } end
	function tab:UseSection(st) curSec = st end

	local function row(h, o, rightW, seed)
		local f = new("Frame", { Parent = scroll, Size = UDim2.new(1, 0, 0, h), BackgroundColor3 = COL.card, BorderSizePixel = 0 }, { corner(11), stroke(accent, 1, 0.72) })
		themed[#themed + 1] = { f:FindFirstChildOfClass("UIStroke"), "Color", "accent" }
		cardGrad(f, false)
		local ib2 = new("Frame", { Parent = f, Position = UDim2.new(0, 10, 0.5, -14), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = accent, BorderSizePixel = 0 }, { corner(8) })
		bind(ib2, "BackgroundColor3", "dim")
		glyph(ib2, seed or o.Name or "x", accent)
		local hasD = o.Desc ~= nil and o.Desc ~= ""
		local t = txt(f, tostring(o.Name or ""), 11, Enum.Font.GothamBold, COL.text, UDim2.new(0, 48, 0, hasD and 7 or 0), UDim2.new(1, -(48 + rightW), 0, hasD and 16 or h))
		local d
		if hasD then d = txt(f, tostring(o.Desc), 9, Enum.Font.Gotham, COL.mut, UDim2.new(0, 48, 0, 24), UDim2.new(1, -(48 + rightW), 0, 14)) end
		tab.rows[#tab.rows + 1] = { f = f, t = t, d = d }
		return f
	end
	local function rowH(o) return (o.Desc ~= nil and o.Desc ~= "") and 48 or 42 end

	function tab:AddSection(text)
		local ord = nextOrder()
		build(function()
			local l = txt(scroll, tostring(text), 9, Enum.Font.GothamBold, accent, UDim2.new(0, 4, 0, 0), UDim2.new(1, 0, 0, 22))
			themed[#themed + 1] = { l, "TextColor3", "accent" }
			l.LayoutOrder = ord
			tab.heads[#tab.heads + 1] = l
		end)
		return {}
	end

	function tab:AddLabel(text)
		local ord = nextOrder()
		local l, cur, col = nil, tostring(text), nil
		build(function()
			local f = new("Frame", { Parent = scroll, Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = COL.card, BorderSizePixel = 0, LayoutOrder = ord }, { corner(11), stroke(accent, 1, 0.78) })
			themed[#themed + 1] = { f:FindFirstChildOfClass("UIStroke"), "Color", "accent" }
			cardGrad(f, false)
			l = txt(f, cur, 11, Enum.Font.Gotham, col or COL.mut, UDim2.new(0, 14, 0, 0), UDim2.new(1, -28, 1, 0))
			tab.rows[#tab.rows + 1] = { f = f, t = l }
		end)
		return {
			Set = function(_, t) cur = tostring(t) if l then l.Text = cur end end,
			SetColor = function(_, c) if typeof(c) == "Color3" then col = c if l then l.TextColor3 = c end end end,
			Get = function() return cur end,
		}
	end

	function tab:AddToggle(o)
		reg(o)
		local ord = nextOrder()
		local state = o.Default == true
		local sw, knob
		local function visual(anim)
			if not sw then return end
			local ti = TweenInfo.new(anim and 0.16 or 0, Enum.EasingStyle.Quad)
			TS:Create(sw, ti, { BackgroundColor3 = state and accent or COL.off }):Play()
			TS:Create(knob, ti, { Position = state and UDim2.new(1, -17, 0.5, -7) or UDim2.new(0, 3, 0.5, -7) }):Play()
		end
		local function set(v, silent)
			state = v and true or false
			visual(true)
			if not silent and o.Callback then task.spawn(o.Callback, state) end
		end
		build(function()
			local f = row(rowH(o), o, 70)
			f.LayoutOrder = ord
			sw = new("Frame", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(36, 20), BackgroundColor3 = COL.off, BorderSizePixel = 0 }, { corner(10) })
			knob = new("Frame", { Parent = sw, Position = UDim2.new(0, 3, 0.5, -7), Size = UDim2.fromOffset(14, 14), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0 }, { corner(7) })
			local hit = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 1, 0), ZIndex = 2 })
			hit.MouseButton1Click:Connect(function() set(not state) end)
			refreshers[#refreshers + 1] = function() visual(false) end
			visual(false)
		end)
		if state and o.Callback then task.defer(o.Callback, state) end
		local obj = {}
		function obj:Set(v, silent) set(v, silent) end
		function obj:Get() return state end
		return obj
	end

	function tab:AddSlider(o)
		reg(o)
		local ord = nextOrder()
		local minV, maxV, step = tonumber(o.Min) or 0, tonumber(o.Max) or 100, tonumber(o.Step) or 1
		local value = math.clamp(tonumber(o.Default) or minV, minV, maxV)
		local fill, knob, valL, track
		local function render()
			if not fill then return end
			local a = (value - minV) / math.max(maxV - minV, 1e-9)
			fill.Size = UDim2.new(a, 0, 1, 0)
			knob.Position = UDim2.new(a, 0, 0.5, 0)
			valL.Text = tostring(value)
		end
		local function set(v, silent)
			v = math.clamp(v, minV, maxV)
			v = math.floor(v / step + 0.5) * step
			if step < 1 then v = math.floor(v * 100 + 0.5) / 100 end
			v = math.clamp(v, minV, maxV)
			if v == value and not silent then return end
			value = v
			render()
			if not silent and o.Callback then task.spawn(o.Callback, value) end
		end
		build(function()
			local f = row(rowH(o), o, 200)
			f.LayoutOrder = ord
			valL = txt(f, "", 10, Enum.Font.GothamBold, accent, UDim2.new(1, -196, 0, 0), UDim2.new(0, 40, 1, 0), Enum.TextXAlignment.Right)
			themed[#themed + 1] = { valL, "TextColor3", "accent" }
			track = new("Frame", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -16, 0.5, 0), Size = UDim2.fromOffset(120, 4), BackgroundColor3 = COL.off, BorderSizePixel = 0 }, { corner(2) })
			fill = new("Frame", { Parent = track, Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = accent, BorderSizePixel = 0 }, { corner(2) })
			themed[#themed + 1] = { fill, "BackgroundColor3", "accent" }
			knob = new("Frame", { Parent = track, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(12, 12), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0 }, { corner(6) })
			local dragging = false
			local function fromX(x)
				local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
				set(minV + (maxV - minV) * a)
			end
			local hit = new("TextButton", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.fromOffset(136, 30), BackgroundTransparency = 1, Text = "", ZIndex = 2 })
			hit.InputBegan:Connect(function(i) if isPress(i) then dragging = true fromX(i.Position.X) end end)
			UIS.InputChanged:Connect(function(i) if dragging and isMove(i) then fromX(i.Position.X) end end)
			UIS.InputEnded:Connect(function(i) if isPress(i) then dragging = false end end)
			render()
		end)
		if o.Callback then task.defer(o.Callback, value) end
		return { Set = function(_, v) set(v) end, Get = function() return value end }
	end

	function tab:AddButton(o)
		reg(o)
		local ord = nextOrder()
		local right
		local obj = {}
		build(function()
			local f = row(rowH(o), o, o.RightText and 120 or 44)
			f.LayoutOrder = ord
			if o.RightText then
				local pill = new("Frame", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(88, 26), BackgroundColor3 = COL.input, BorderSizePixel = 0 }, { corner(8), stroke(accent, 1, 0.6) })
				right = txt(pill, tostring(o.RightText), 10, Enum.Font.GothamBold, COL.text, UDim2.new(), UDim2.new(1, 0, 1, 0), Enum.TextXAlignment.Center)
			else
				local ar = txt(f, ">", 14, Enum.Font.GothamBold, accent, UDim2.new(1, -30, 0, 0), UDim2.new(0, 16, 1, 0), Enum.TextXAlignment.Center)
				themed[#themed + 1] = { ar, "TextColor3", "accent" }
			end
			local hit = new("TextButton", { Parent = f, BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 1, 0), ZIndex = 2 })
			hit.MouseEnter:Connect(function() TS:Create(f, TweenInfo.new(0.12), { BackgroundTransparency = 0.25 }):Play() end)
			hit.MouseLeave:Connect(function() TS:Create(f, TweenInfo.new(0.12), { BackgroundTransparency = 0 }):Play() end)
			hit.MouseButton1Click:Connect(function()
				if o.Callback then task.spawn(o.Callback) end
			end)
		end)
		function obj:SetRight(t) if right then right.Text = tostring(t) end end
		return obj
	end

	local function dropBtn(f, w)
		local btn = new("TextButton", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(w, 26), BackgroundColor3 = COL.input, BorderSizePixel = 0, Text = "", AutoButtonColor = false }, { corner(8), stroke(accent, 1, 0.65) })
		themed[#themed + 1] = { btn:FindFirstChildOfClass("UIStroke"), "Color", "accent" }
		local cl = txt(btn, "", 10, Enum.Font.GothamBold, COL.text, UDim2.new(0, 9, 0, 0), UDim2.new(1, -26, 1, 0))
		local ch = txt(btn, "v", 10, Enum.Font.GothamBold, accent, UDim2.new(1, -18, 0, 0), UDim2.new(0, 12, 1, 0), Enum.TextXAlignment.Center)
		themed[#themed + 1] = { ch, "TextColor3", "accent" }
		return btn, cl
	end

	function tab:AddDropdown(o)
		reg(o)
		local ord = nextOrder()
		local opts = o.Options or {}
		local currentV = o.Default
		local curL
		local function refresh() if curL then curL.Text = (currentV ~= nil and tostring(currentV) or "Chọn...") end end
		local function pick(op, silent)
			currentV = op
			refresh()
			if not silent and o.Callback then task.spawn(o.Callback, currentV) end
		end
		build(function()
			local f = row(rowH(o), o, 140)
			f.LayoutOrder = ord
			local btn, cl = dropBtn(f, 112)
			curL = cl
			refresh()
			btn.MouseButton1Click:Connect(function()
				openPopup(btn, opts, function(n) return tostring(currentV) == n end, function(n) pick(n) end, false)
			end)
		end)
		if currentV ~= nil and o.Callback then task.defer(o.Callback, currentV) end
		return {
			Get = function() return currentV end,
			Set = function(_, v) pick(v) end,
			SetOptions = function(_, l) opts = l or {} currentV = nil refresh() end,
		}
	end

	function tab:AddMultiDropdown(o)
		reg(o)
		local ord = nextOrder()
		local prio = o.Priority == true
		local opts, sel, ordL = o.Options or {}, {}, {}
		local curL
		local function summary()
			if prio then return #ordL > 0 and table.concat(ordL, " > ") or "Chọn..." end
			local n = 0
			for _, v in pairs(sel) do if v then n = n + 1 end end
			return n > 0 and (n .. " đã chọn") or "Chọn..."
		end
		local function refresh() if curL then curL.Text = summary() end end
		local function toggle(name, on, silent)
			on = on and true or false
			sel[name] = on
			if prio then
				for i = #ordL, 1, -1 do if ordL[i] == name then table.remove(ordL, i) end end
				if on then ordL[#ordL + 1] = name end
			end
			refresh()
			if not silent and o.Callback then
				if prio then task.spawn(o.Callback, table.clone(ordL)) else task.spawn(o.Callback, name, on) end
			end
		end
		build(function()
			local f = row(rowH(o), o, 150)
			f.LayoutOrder = ord
			local btn, cl = dropBtn(f, 122)
			curL = cl
			refresh()
			btn.MouseButton1Click:Connect(function()
				openPopup(btn, opts, function(n) return sel[n] == true end, function(n) toggle(n, not sel[n]) end, true)
			end)
		end)
		for _, n in ipairs(o.Init or {}) do toggle(tostring(n), true, true) end
		return {
			SetValue = function(_, v)
				if type(v) == "table" then
					if #v > 0 then for _, n in ipairs(v) do toggle(tostring(n), true) end
					else for n, on in pairs(v) do if on == true then toggle(tostring(n), true) end end end
				elseif v ~= nil then toggle(tostring(v), true) end
			end,
			Refresh = function(_, names, init)
				opts, sel, ordL = names or {}, {}, {}
				for _, n in ipairs(init or {}) do toggle(tostring(n), true, true) end
				refresh()
			end,
		}
	end

	function tab:AddBox(o)
		reg(o)
		local ord = nextOrder()
		local text = o.Default ~= nil and tostring(o.Default) or ""
		local tb, sw
		local obj = {}
		build(function()
			local f = row(rowH(o), o, o.Swatch and 220 or 200)
			f.LayoutOrder = ord
			local wBox = o.Swatch and 120 or 156
			tb = new("TextBox", {
				Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, o.Swatch and -46 or -14, 0.5, 0), Size = UDim2.fromOffset(wBox, 26),
				Text = text, PlaceholderText = o.Placeholder or "", ClearTextOnFocus = false, Font = Enum.Font.Gotham, TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = COL.text, PlaceholderColor3 = COL.mut, BackgroundColor3 = COL.input, BorderSizePixel = 0,
			}, { corner(8), stroke(accent, 1, 0.65), new("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }) })
			if o.Swatch then
				sw = new("Frame", { Parent = f, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = o.Swatch(), BorderSizePixel = 0 }, { corner(8) })
			end
			tb.FocusLost:Connect(function()
				if o.Numeric then tb.Text = tb.Text:gsub("[^%d%.%-]", "") end
				text = tb.Text
				if o.Callback then task.spawn(o.Callback, tb.Text) end
			end)
		end)
		if text ~= "" and o.Callback then task.defer(o.Callback, text) end
		function obj:Set(v) text = tostring(v) if tb then tb.Text = text end if o.Callback then task.spawn(o.Callback, text) end end
		function obj:Get() return tb and tb.Text or text end
		function obj:SetSwatch(c) if sw then sw.BackgroundColor3 = c end end
		return obj
	end

	return tab
end
