local WS = { open = false, tok = 0, compact = false }
local function transpG() return math.clamp((tonumber(cfg.transp) or 0) / 100, 0, 1) * 0.85 end
local function setOpen(v)
	v = v and true or false
	if v == WS.open then return end
	WS.open = v
	getgenv().UIToggled = v
	WS.tok = WS.tok + 1
	local tok = WS.tok
	closePopup()
	if v then
		win.Visible = true
		uiScale.Scale = fit() * 0.92
		win.GroupTransparency = 1
		if not curPage then showPage("home") end
		TS:Create(uiScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = fit() }):Play()
		TS:Create(win, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { GroupTransparency = transpG() }):Play()
	else
		TS:Create(uiScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = fit() * 0.94 }):Play()
		TS:Create(win, TweenInfo.new(0.18, Enum.EasingStyle.Quad), { GroupTransparency = 1 }):Play()
		task.delay(0.22, function() if WS.tok == tok and not WS.open then win.Visible = false end end)
	end
end
