local function applyTheme()
	for i = #themed, 1, -1 do
		local t = themed[i]
		local ok = pcall(function() t[1][t[2]] = themeVal(t[3]) end)
		if not ok then table.remove(themed, i) end
	end
	for i = #grads, 1, -1 do
		local ok = pcall(paintGrad, grads[i][1], grads[i][2])
		if not ok then table.remove(grads, i) end
	end
	for _, r in ipairs(refreshers) do pcall(r) end
end

