	local keyBtn
	keyBtn = ui:AddButton({
		Name = "Toggle UI", Desc = "Phím ẩn/hiện menu", RightText = cfg.key,
		Callback = function()
			keyBtn:SetRight("...")
			local c
			c = UIS.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.Keyboard then
					c:Disconnect()
					toggleKey = i.KeyCode.Name
					cfg.key = toggleKey
					saveCfg()
					keyBtn:SetRight(toggleKey)
				end
			end)
		end,
	})
	local accBox
	local first = true
	ui:AddDropdown({
		Name = "Theme", Desc = "Đổi tông màu menu", Options = (function() local l = {} for _, t in ipairs(THEMES) do l[#l + 1] = t[1] end return l end)(),
		Default = cfg.theme,
		Callback = function(v)
			if first then first = false return end
			cfg.accent = nil
			pickTheme(v)
			saveCfg()
			applyTheme()
			if accBox then accBox:SetSwatch(accent) end
		end,
	})
	ui:AddSlider({
		Name = "Transparency", Desc = "Độ trong suốt của menu", Min = 0, Max = 100, Default = tonumber(cfg.transp) or 0,
		Callback = function(v)
			cfg.transp = v
			saveCfg()
			if WS.open then win.GroupTransparency = transpG() end
		end,
	})
	accBox = ui:AddBox({
		Name = "Accent Color", Desc = "Màu nhấn của menu (mã HEX)", Default = "#" .. accent:ToHex():upper(), Placeholder = "#RRGGBB",
		Swatch = function() return accent end,
		Callback = function(v)
			local ok, c = pcall(function() return Color3.fromHex(v) end)
			if ok and c then
				accent = c
				cfg.accent = c:ToHex()
				saveCfg()
				applyTheme()
				if accBox then accBox:SetSwatch(c) end
			end
		end,
	})
end
