Library.DestroyUI = function()
	if game.CoreGui:FindFirstChild("Windy Hub GUI") then
		for i, v in ipairs(game.CoreGui:GetChildren()) do
			if string.find(v.Name,  "Windy Hub") then
				v:Destroy()
			end
		end
	end
end

if true then
	local button = btnHide
	local pressed, dragging = false, false
	local dragInput, dragStart
	local sx, sy, ox, oy = 0, 1, 0, 0
	local gx, gy, cx, cy = 0, 0, 0, 0
	local active = false
	getgenv().__WindyBtnMoved = false

	local function bounds()
		local a = Library_Function.HideGui.AbsoluteSize
		return a.X, a.Y
	end
	local function clampOff(x, y)
		local W, H = bounds()
		if W <= 0 or H <= 0 then return x, y end
		local bw, bh = button.AbsoluteSize.X, button.AbsoluteSize.Y
		local ax = math.clamp(sx * W + x, 0, math.max(W - bw, 0))
		local ay = math.clamp(sy * H + y, math.min(bh, H), H)
		return ax - sx * W, ay - sy * H
	end

	button.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			pressed, dragging = true, false
			dragStart, dragInput = input.Position, input
			local pos = button.Position
			sx, sy, ox, oy = pos.X.Scale, pos.Y.Scale, pos.X.Offset, pos.Y.Offset
			cx, cy, gx, gy = ox, oy, ox, oy
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					pressed = false
					if dragging then
						dragging = false
						-- hut vao mep trai/phai gan nhat cho gon
						local W = bounds()
						local bw = button.AbsoluteSize.X
						if W > 0 then
							local centerX = sx * W + gx + bw / 2
							local targetX = (centerX < W / 2) and 10 or (W - bw - 10)
							local nx, ny = clampOff(targetX - sx * W, gy)
							gx, gy = nx, ny
						end
						active = true
						task.delay(0.35, function() getgenv().__WindyBtnMoved = false end)
					end
				end
			end)
		end
	end)
	uis.InputChanged:Connect(function(input)
		if pressed and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			dragInput = input
		end
	end)
	RunService.RenderStepped:Connect(function(dt)
		if pressed and dragInput and dragStart then
			local d = dragInput.Position - dragStart
			if not dragging and d.Magnitude > 7 then
				dragging = true
				getgenv().__WindyBtnMoved = true
			end
			if dragging then
				gx, gy = clampOff(ox + d.X, oy + d.Y)
				active = true
			end
		end
		if active then
			local a = 1 - math.exp(-dt * 22)
			cx = cx + (gx - cx) * a
			cy = cy + (gy - cy) * a
			button.Position = UDim2.new(sx, cx, sy, cy)
			if not pressed and math.abs(gx - cx) < 0.4 and math.abs(gy - cy) < 0.4 then
				button.Position = UDim2.new(sx, gx, sy, gy)
				active = false
			end
		end
	end)
end

btnHide.MouseButton1Click:Connect(function()
	if getgenv().__WindyBtnMoved then return end
	Library.ToggleUI()
end)

uis.InputBegan:Connect(function(input)
	if not uis:GetFocusedTextBox() and (input.KeyCode == Enum.KeyCode.LeftControl or input.KeyCode == Enum.KeyCode.RightControl) then
		Library.ToggleUI()
	end
end)

