------------------------------------------------------------------ INTRO + THANH STATUS (theo video, mau chu dao Windy)
function __WindyIntroStatus(ui)
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	local ACCENT = (ui and ui.accent and ui.accent()) or Color3.fromRGB(146, 208, 236)
	local CG = game:GetService("CoreGui")
	local TXS = game:GetService("TextService")
	for _, n in ipairs({ "Windy Hub Intro", "Windy Hub Status" }) do
		local o = CG:FindFirstChild(n)
		if o then o:Destroy() end
	end
	local function clamp01(x) return math.max(0, math.min(1, x)) end
	local function outCubic(t) return 1 - (1 - t) ^ 3 end
	local function outBack(t) local c1, c3 = 1.70158, 2.70158 return 1 + c3 * (t - 1) ^ 3 + c1 * (t - 1) ^ 2 end
	local function round(o, r) local c = Instance.new("UICorner") c.CornerRadius = r or UDim.new(0, 12) c.Parent = o return c end
	local function outline(o, col, th, tr) local s = Instance.new("UIStroke") s.Color = col or ACCENT s.Thickness = th or 1.2 s.Transparency = tr or 0.4 s.Parent = o return s end
	local function label(parent, text, size, font, col, y, h)
		local l = Instance.new("TextLabel")
		l.BackgroundTransparency = 1 l.AnchorPoint = Vector2.new(0.5, 0) l.Position = UDim2.new(0.5, 0, 0, y) l.Size = UDim2.new(1, -30, 0, h)
		l.Text = text l.TextSize = size l.Font = font l.TextColor3 = col l.Parent = parent
		return l
	end

	-------------------------------------------------- thanh status (vien thuoc o giua tren cung)
	local sg = Instance.new("ScreenGui")
	sg.Name = "Windy Hub Status" sg.IgnoreGuiInset = true sg.ResetOnSpawn = false sg.DisplayOrder = 999
	sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	sg.Parent = CG
	local pill = Instance.new("Frame")
	pill.AnchorPoint = Vector2.new(0.5, 0)
	pill.Position = UDim2.new(0.5, 0, 0, -44)
	pill.Size = UDim2.fromOffset(170, 30)
	pill.BackgroundColor3 = Color3.fromRGB(10, 12, 16)
	pill.BackgroundTransparency = 0.04
	pill.BorderSizePixel = 0
	pill.Parent = sg
	round(pill, UDim.new(1, 0))
	outline(pill, ACCENT, 1.2, 0.55)
	local dot = Instance.new("Frame")
	dot.AnchorPoint = Vector2.new(0, 0.5) dot.Position = UDim2.new(0, 13, 0.5, 0) dot.Size = UDim2.fromOffset(8, 8)
	dot.BackgroundColor3 = ACCENT dot.BorderSizePixel = 0 dot.Parent = pill
	round(dot, UDim.new(1, 0))
	local lab = Instance.new("TextLabel")
	lab.BackgroundTransparency = 1 lab.Position = UDim2.new(0, 29, 0, 0) lab.Size = UDim2.new(1, -40, 1, 0)
	lab.Font = Enum.Font.GothamMedium lab.TextSize = 12 lab.TextColor3 = Color3.fromRGB(235, 244, 250)
	lab.TextXAlignment = Enum.TextXAlignment.Left lab.TextTruncate = Enum.TextTruncate.AtEnd lab.Text = "" lab.Parent = pill

	local kinds = {
		ok = Color3.fromRGB(120, 230, 160), warn = Color3.fromRGB(255, 200, 90),
		info = ACCENT, err = Color3.fromRGB(255, 110, 110),
	}
	local cur, curKind, tempUntil, pillShown = nil, nil, 0, false
	local function apply(text, kind)
		if text == cur and kind == curKind then return end
		cur, curKind = text, kind
		lab.Text = text
		local w = 150
		pcall(function() w = TXS:GetTextSize(text, 12, Enum.Font.GothamMedium, Vector2.new(900, 30)).X + 46 end)
		local cam = workspace.CurrentCamera
		local maxW = cam and math.max(160, cam.ViewportSize.X - 140) or 600
		w = math.clamp(w, 130, maxW)
		TweenService:Create(pill, TweenInfo.new(0.32, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(w, 30) }):Play()
		TweenService:Create(dot, TweenInfo.new(0.3), { BackgroundColor3 = kinds[kind] or ACCENT }):Play()
		lab.TextTransparency = 1
		TweenService:Create(lab, TweenInfo.new(0.28), { TextTransparency = 0 }):Play()
	end
	local baseText, baseKind = "Windy Hub • Đang tải script...", "warn"
	getgenv().WindyStatus = function(text, kind, hold)
		text = tostring(text or "")
		if hold then
			tempUntil = os.clock() + math.min(tonumber(hold) or 4, 8)
			apply(text, kind or "info")
		else
			baseText, baseKind = text, kind or "info"
			if os.clock() >= tempUntil then apply(baseText, baseKind) end
		end
	end
	local function showPill()
		if pillShown then return end
		pillShown = true
		TweenService:Create(pill, TweenInfo.new(0.55, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Position = UDim2.new(0.5, 0, 0, 12) }):Play()
	end
	apply(baseText, baseKind)
	task.spawn(function()
		task.wait(3.5)
		showPill()
		while sg.Parent do
			task.wait(0.6)
			if os.clock() >= tempUntil then
				local text, kind
				if not getgenv().__WindyLoaded then
					text, kind = "Windy Hub • Đang tải script...", "warn"
				else
					local okS, S = pcall(function() return Settings end)
					if okS and type(S) == "table" and S["Start Farm"] then
						text, kind = "Windy Hub • Đang farm: " .. tostring(S["Select Method Farm"] or "Farm"), "ok"
					else
						text, kind = "Windy Hub • Sẵn sàng", "ok"
					end
				end
				baseText, baseKind = text, kind
				apply(text, kind)
			end
		end
	end)

	-------------------------------------------------- intro: 2 net muc lao xuong -> bang mo ra -> thanh tai
	local ig = Instance.new("ScreenGui")
	ig.Name = "Windy Hub Intro" ig.IgnoreGuiInset = true ig.ResetOnSpawn = false ig.DisplayOrder = 1000
	ig.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	ig.Parent = CG

	local function mkStroke()
		local f = Instance.new("Frame")
		f.AnchorPoint = Vector2.new(0.5, 0.5) f.BackgroundColor3 = ACCENT f.BorderSizePixel = 0
		f.Size = UDim2.fromOffset(0, 0) f.Parent = ig
		round(f, UDim.new(1, 0))
		local s = outline(f, Color3.fromRGB(225, 244, 255), 2, 0.55)
		return f, s
	end
	local sL, sLs = mkStroke()
	local sR, sRs = mkStroke()

	local ring = Instance.new("Frame")
	ring.AnchorPoint = Vector2.new(0.5, 0.5) ring.BackgroundTransparency = 1 ring.Size = UDim2.fromOffset(0, 0) ring.Parent = ig
	round(ring, UDim.new(1, 0))
	local ringS = outline(ring, ACCENT, 3, 1)

	local cw, ch = 420, 250
	local card = Instance.new("Frame")
	card.AnchorPoint = Vector2.new(0.5, 0.5) card.Position = UDim2.new(0.5, 0, 0.5, 0) card.Size = UDim2.fromOffset(0, 0)
	card.BackgroundColor3 = Color3.fromRGB(8, 12, 18) card.BackgroundTransparency = 1 card.BorderSizePixel = 0
	card.ClipsDescendants = true card.Parent = ig
	round(card, UDim.new(0, 20))
	local cardS = outline(card, ACCENT, 1.5, 1)
	local inner = Instance.new("Frame")
	inner.AnchorPoint = Vector2.new(0.5, 0.5) inner.Position = UDim2.new(0.5, 0, 0.5, 0) inner.Size = UDim2.fromOffset(cw, ch)
	inner.BackgroundTransparency = 1 inner.Parent = card

	local logo = Instance.new("ImageLabel")
	logo.BackgroundTransparency = 1 logo.AnchorPoint = Vector2.new(0.5, 0) logo.Position = UDim2.new(0.5, 0, 0, 22)
	logo.Size = UDim2.fromOffset(92, 92) logo.ScaleType = Enum.ScaleType.Fit logo.Parent = inner
	pcall(function() logo.Image = (ui and ui.logoAsset) or "" end)
	local title = label(inner, "Windy Hub", 26, Enum.Font.GothamBold, Color3.fromRGB(240, 248, 255), 118, 30)
	local sub = label(inner, "Blox Fruits  •  Việt Hoá", 13, Enum.Font.Gotham, ACCENT, 150, 16)
	local track = Instance.new("Frame")
	track.AnchorPoint = Vector2.new(0.5, 0) track.Position = UDim2.new(0.5, 0, 0, 184) track.Size = UDim2.fromOffset(cw - 100, 6)
	track.BackgroundColor3 = Color3.fromRGB(28, 38, 50) track.BorderSizePixel = 0 track.Parent = inner
	round(track, UDim.new(1, 0))
	local fill = Instance.new("Frame")
	fill.Size = UDim2.new(0, 0, 1, 0) fill.BackgroundColor3 = ACCENT fill.BorderSizePixel = 0 fill.Parent = track
	round(fill, UDim.new(1, 0))
	local grad = Instance.new("UIGradient")
	grad.Color = ColorSequence.new(Color3.fromRGB(190, 232, 250), Color3.fromRGB(110, 185, 225))
	grad.Parent = fill
	local stat = label(inner, "Đang khởi tạo...", 12, Enum.Font.Gotham, Color3.fromRGB(165, 182, 198), 200, 16)

	local function fadeAll(a) -- a: 0 = hien, 1 = an
		logo.ImageTransparency = a
		title.TextTransparency, sub.TextTransparency, stat.TextTransparency = a, a, a
		track.BackgroundTransparency = a + (1 - a) * 0
		fill.BackgroundTransparency = a
	end
	fadeAll(1)

	local t0, last = os.clock(), os.clock()
	local tFin, tEx, opened, conn = nil, nil, false, nil
	local progress = 0
	local function openMenu()
		if opened then return end
		opened = true
		pcall(function()
			if ui and ui.isOpen and not ui.isOpen() then ui.toggle() end
		end)
	end
	conn = RunService.RenderStepped:Connect(function()
		if not ig.Parent then conn:Disconnect() return end
		local now = os.clock()
		local e = now - t0
		local cam = workspace.CurrentCamera
		local v = cam and cam.ViewportSize or Vector2.new(1280, 720)
		local W, H = v.X, v.Y
		local cxm, cym = W / 2, H / 2

		-- 2 net muc tu tren xuong, hoi tu ve giua
		local function seg(f, fs, x0, y0, t, fade)
			local x1, y1 = x0 + (cxm - x0) * t, y0 + (cym - y0) * t
			local dx, dy = x1 - x0, y1 - y0
			local len = math.sqrt(dx * dx + dy * dy)
			f.Position = UDim2.fromOffset((x0 + x1) / 2, (y0 + y1) / 2)
			f.Size = UDim2.fromOffset(math.max(2, 9 * (1 - t * 0.55)), len)
			f.Rotation = math.deg(math.atan2(dy, dx)) - 90
			f.BackgroundTransparency = fade
			fs.Transparency = 0.55 + 0.45 * fade
		end
		local st = outCubic(clamp01(e / 0.7))
		local sfade = clamp01((e - 0.72) / 0.28)
		if sfade < 1 then
			seg(sL, sLs, W * 0.2, -30, st, sfade)
			seg(sR, sRs, W * 0.8, -30, st, sfade)
		else
			sL.Visible, sR.Visible = false, false
		end

		-- vong no tai diem hoi tu
		local rp = clamp01((e - 0.62) / 0.5)
		if rp > 0 and rp < 1 then
			ring.Position = UDim2.fromOffset(cxm, cym)
			local d = 20 + 300 * outCubic(rp)
			ring.Size = UDim2.fromOffset(d, d)
			ringS.Transparency = rp
		else
			ringS.Transparency = 1
		end

		-- bang mo ra
		local pe = clamp01((e - 0.72) / 0.65)
		local k = (pe > 0) and outBack(pe) or 0
		local scale = k
		local fadeIn = clamp01((e - 0.72) / 0.3)
		local a = 1 - fadeIn
		if tEx then
			local x = clamp01((now - tEx) / 0.45)
			scale = 1 - 0.12 * x
			a = x
		end
		card.Size = UDim2.fromOffset(math.max(0, cw * scale), math.max(0, ch * scale))
		card.BackgroundTransparency = 0.1 + 0.9 * a
		cardS.Transparency = 0.3 + 0.7 * a
		fadeAll(math.max(a, 1 - clamp01((e - 1.0) / 0.35)))

		if e > 0.9 then pcall(showPill) end

		-- thanh tai
		if not tEx then
			local ready = getgenv().__WindyLoaded == true or e > 20
			local base = math.min(0.9, math.max(0, (e - 1.2) / 2.4))
			if ready and e >= 2.4 and not tFin then tFin = now end
			if tFin then
				progress = base + (1 - base) * clamp01((now - tFin) / 0.35)
				stat.Text = "Hoàn tất!"
				if now - tFin >= 0.7 then tEx = now openMenu() end
			else
				progress = base
				stat.Text = (e < 1.6) and "Đang khởi tạo..." or ("Đang tải chức năng... " .. math.floor(progress * 100) .. "%")
			end
			fill.Size = UDim2.new(clamp01(progress), 0, 1, 0)
		elseif now - tEx >= 0.45 then
			conn:Disconnect()
			ig:Destroy()
			pcall(function() getgenv().WindyStatus("Windy Hub • Sẵn sàng", "ok") end)
		end
	end)
end


