getgenv().UIToggled = false -- luon bat dau o trang thai an, tranh lech trang thai khi chay lai script
local PREF = { "Farm", "Khu Vực", "Sea Event", "Raid & Fruit", "Race & Items", "Fishing & Quest", "Event", "Halloween", "Player", "Shop", "Setting" }
local function orderOf(name)
	for i, n in ipairs(PREF) do if n == name then return i end end
	return 100
end
local function VT(s)
	if s == nil then return nil end
	s = tostring(s)
	local ok, r = pcall(function()
		local T = getgenv().WindyTranslator
		if T and T.Translate then return T.Translate(s) end
	end)
	if ok and type(r) == "string" and r ~= "" then return r end
	return s
end

local api = { Flags = {}, gui = nil }
local tabs, built, fb = {}, false, nil
local DEFAULT = { title = "", rank = 0, n = 0 }
local seqN, uidN = 0, 0
local function uid(p) uidN = uidN + 1 return p .. uidN end

-- ===== dung phan tu that cua Real Kid UI =====
local function realize(t, it)
	local box = it.box
	local o, ctl, cb = it.o, it, it.o and it.o.Callback
	if it.kind == "toggle" then
		ctl.mute = true
		local okc, real = pcall(function()
			return box:AddToggle(uid("t"), {
				Title = VT(o.Name), Desc = VT(o.Desc), Default = ctl.value,
				Callback = function(v)
					v = v and true or false
					ctl.value = v
					if ctl.mute then return end
					if cb then task.spawn(cb, v) end
				end,
			})
		end)
		ctl.mute = false
		if okc then ctl.real = real else warn("[Windy] toggle loi:", real) end
	elseif it.kind == "slider" then
		ctl.mute = true
		local okc, real = pcall(function()
			return box:AddSlider({
				Title = VT(o.Name), Min = ctl.min, Max = ctl.max, Default = ctl.value, Precise = ctl.step < 1,
				Callback = function(v)
					ctl.value = v
					if ctl.mute then return end
					if cb then task.spawn(cb, v) end
				end,
			})
		end)
		ctl.mute = false
		if okc then ctl.real = real else warn("[Windy] slider loi:", real) end
	elseif it.kind == "button" then
		local okc, real = pcall(function()
			return box:AddButton({
				Title = VT(o.Name), Desc = VT(o.Desc),
				Callback = function() if cb then task.spawn(cb) end end,
			})
		end)
		if okc then ctl.real = real else warn("[Windy] button loi:", real) end
	elseif it.kind == "label" then
		local okc, real = pcall(function() return box:AddLabel(VT(ctl.text)) end)
		if okc then ctl.real = real else warn("[Windy] label loi:", real) end
	elseif it.kind == "box" then
		ctl.mute = true
		local okc, real = pcall(function()
			return box:AddInput(uid("i"), {
				Title = VT(o.Name), Placeholder = o.Placeholder or "", Default = (ctl.value ~= "" and ctl.value) or nil, Numeric = o.Numeric,
				Callback = function(v)
					v = tostring(v or "")
					ctl.value = v
					if ctl.mute then return end
					if cb then task.spawn(cb, v) end
				end,
			})
		end)
		ctl.mute = false
		if okc then ctl.real = real else warn("[Windy] input loi:", real) end
	elseif it.kind == "dropdown" then
		ctl.mute = true
		local okc, real = pcall(function()
			return box:AddDropdown(uid("d"), {
				Title = VT(o.Name), Values = ctl.opts, Default = ctl.value,
				Callback = function(v)
					ctl.value = v
					if ctl.mute then return end
					if cb then task.spawn(cb, v) end
				end,
			})
		end)
		ctl.mute = false
		if okc then ctl.real = real else warn("[Windy] dropdown loi:", real) end
	elseif it.kind == "multi" then
		ctl.mute = true
		local init = {}
		for _, n in ipairs(ctl.opts) do if ctl.sel[n] then init[#init + 1] = n end end
		local okc, real = pcall(function()
			return box:AddDropdown(uid("m"), {
				Title = VT(o.Name), Values = ctl.opts, Selected = true, Default = init,
				Callback = function(name, on)
					if ctl.mute then return end
					ctl.onUI(name, on)
				end,
			})
		end)
		ctl.mute = false
		if okc then ctl.real = real else warn("[Windy] multi dropdown loi:", real) end
	end
end

-- ===== proxy tab (xep muc theo rank truoc khi dung that) =====
local function makeTab(name, title)
	seqN = seqN + 1
	local t = { name = name, title = title or name, secs = {}, order = {}, cur = nil, seq = seqN, page = nil }
	local function sec(st)
		st = st or DEFAULT
		local s = t.secs[st]
		if not s then
			s = { st = st, items = {}, idx = #t.order + 1 }
			t.secs[st] = s
			t.order[#t.order + 1] = s
		end
		return s
	end
	function t:UseSection(st) self.cur = st sec(st) end
	function t:AddSection(_) end
	local function push(it)
		it.tab = t
		local s = sec(t.cur)
		if t.page then
			-- da dung giao dien: them truc tiep vao nhom cua muc
			if not s.box then
				local okb, b = pcall(function() return t.page:AddLeftGroupbox(VT(s.st.title ~= "" and s.st.title or t.name)) end)
				if okb then s.box = b end
			end
			it.box = s.box
			if it.box then realize(t, it) end
		else
			s.items[#s.items + 1] = it
		end
	end
	tabs[#tabs + 1] = t

	function t:AddToggle(o)
		local ctl = { kind = "toggle", o = o, value = (o.Default == true) }
		if ctl.value and o.Callback then task.defer(o.Callback, true) end
		function ctl:Set(v, silent)
			v = v and true or false
			self.value = v
			if self.fb then self.fb:Set(v, true)
			elseif self.real then
				self.mute = true
				pcall(self.real.SetStage, v)
				self.mute = false
			end
			if not silent and o.Callback then task.spawn(o.Callback, v) end
		end
		function ctl:Get() return self.value end
		push(ctl)
		return ctl
	end

	function t:AddSlider(o)
		local minV, maxV, step = tonumber(o.Min) or 0, tonumber(o.Max) or 100, tonumber(o.Step) or 1
		local ctl = { kind = "slider", o = o, min = minV, max = maxV, step = step, value = math.clamp(tonumber(o.Default) or minV, minV, maxV) }
		if o.Callback then task.defer(o.Callback, ctl.value) end
		function ctl:Set(v)
			v = math.clamp(tonumber(v) or self.value, minV, maxV)
			self.value = v
			if self.fb then self.fb:Set(v)
			elseif self.real then
				self.mute = true
				pcall(self.real.SetValue, v)
				self.mute = false
			end
			if o.Callback then task.spawn(o.Callback, v) end
		end
		function ctl:Get() return self.value end
		push(ctl)
		return ctl
	end

	function t:AddButton(o)
		local ctl = { kind = "button", o = o }
		push(ctl)
		return ctl
	end

	function t:AddLabel(text)
		local ctl = { kind = "label", o = {}, text = tostring(text) }
		function ctl:Set(v)
			self.text = tostring(v)
			if self.fb then self.fb:Set(self.text)
			elseif self.real then pcall(function() self.real:SetText(self.text) end) end
		end
		function ctl:SetColor(c)
			if self.fb then self.fb:SetColor(c)
			elseif self.real and typeof(c) == "Color3" then pcall(self.real.SetColor, c) end
		end
		function ctl:Get() return self.text end
		push(ctl)
		return ctl
	end

	function t:AddBox(o)
		local ctl = { kind = "box", o = o, value = o.Default ~= nil and tostring(o.Default) or "" }
		if ctl.value ~= "" and o.Callback then task.defer(o.Callback, ctl.value) end
		function ctl:Set(v)
			v = tostring(v)
			self.value = v
			if self.fb then self.fb:Set(v)
			elseif self.real then
				self.mute = true
				pcall(self.real.SetValue, v)
				self.mute = false
			end
			if o.Callback then task.spawn(o.Callback, v) end
		end
		function ctl:Get() return self.value end
		push(ctl)
		return ctl
	end

	function t:AddDropdown(o)
		local ctl = { kind = "dropdown", o = o, opts = o.Options or {}, value = o.Default }
		if ctl.value ~= nil and o.Callback then task.defer(o.Callback, ctl.value) end
		function ctl:Set(v)
			self.value = v
			if self.fb then self.fb:Set(v)
			elseif self.real then
				self.mute = true
				pcall(function() self.real:SetValue(v) end)
				self.mute = false
			end
			if o.Callback then task.spawn(o.Callback, v) end
		end
		function ctl:SetOptions(l)
			self.opts = l or {}
			self.value = nil
			if self.fb then self.fb:SetOptions(self.opts)
			elseif self.real then pcall(function() self.real:GetNewList(self.opts) end) end
		end
		function ctl:Get() return self.value end
		push(ctl)
		return ctl
	end

	function t:AddMultiDropdown(o)
		local prio = o.Priority == true
		local ctl = { kind = "multi", o = o, opts = {}, sel = {}, ord = {} }
		for _, n in ipairs(o.Options or {}) do ctl.opts[#ctl.opts + 1] = n end
		local function fire(name, on)
			if not o.Callback then return end
			if prio then task.spawn(o.Callback, table.clone(ctl.ord)) else task.spawn(o.Callback, name, on) end
		end
		local function setSel(name, on, silent)
			on = on and true or false
			ctl.sel[name] = on
			if prio then
				for i = #ctl.ord, 1, -1 do if ctl.ord[i] == name then table.remove(ctl.ord, i) end end
				if on then ctl.ord[#ctl.ord + 1] = name end
			end
			if not silent then fire(name, on) end
		end
		function ctl.onUI(name, on) setSel(tostring(name), on) end
		for _, n in ipairs(o.Init or {}) do setSel(n, true) end
		local function realSet(name)
			if ctl.fb then pcall(function() ctl.fb:SetValue({ name }) end)
			elseif ctl.real then
				ctl.mute = true
				pcall(function() ctl.real:SetValue(name) end)
				ctl.mute = false
			end
		end
		function ctl:SetValue(v)
			local names = {}
			if type(v) == "table" then
				if #v > 0 then for _, n in ipairs(v) do names[#names + 1] = tostring(n) end
				else for n, on in pairs(v) do if on == true then names[#names + 1] = tostring(n) end end end
			elseif v ~= nil then names[1] = tostring(v) end
			for _, n in ipairs(names) do setSel(n, true) realSet(n) end
		end
		function ctl:Refresh(names, init)
			local keep = {}
			for _, n in ipairs(names or {}) do keep[n] = true end
			for n, on in pairs(self.sel) do if on and not keep[n] then setSel(n, false, true) end end
			self.opts = {}
			for _, n in ipairs(names or {}) do self.opts[#self.opts + 1] = n end
			if self.fb then self.fb:Refresh(self.opts, init)
			elseif self.real then
				self.mute = true
				pcall(function() self.real:GetNewList(self.opts) end)
				self.mute = false
			end
			for _, n in ipairs(init or {}) do setSel(n, true) realSet(n) end
		end
		push(ctl)
		return ctl
	end
	return t
end

local function sortedTabs()
	local l = {}
	for _, t in ipairs(tabs) do l[#l + 1] = t end
	table.sort(l, function(a, b)
		local oa, ob = orderOf(a.name), orderOf(b.name)
		if oa ~= ob then return oa < ob end
		return a.seq < b.seq
	end)
	return l
end
local function sortedSecs(t)
	local l = {}
	for _, s in ipairs(t.order) do l[#l + 1] = s end
	table.sort(l, function(a, b)
		local ra, rb = a.st.rank or 50, b.st.rank or 50
		if ra ~= rb then return ra < rb end
		return a.idx < b.idx
	end)
	return l
end

------------------------------------------------------------------ LOGO WINDY
local logoAsset
local function b64dec(data)
	local ok, r = pcall(function()
		if crypt and crypt.base64decode then return crypt.base64decode(data) end
		if base64_decode then return base64_decode(data) end
		if base64 and base64.decode then return base64.decode(data) end
		error("no")
	end)
	if ok and r and #r > 0 then return r end
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local map = {}
	for i = 1, 64 do map[chars:sub(i, i)] = i - 1 end
	data = data:gsub("[^%w%+/=]", "")
	local out, n = {}, 0
	for i = 1, #data, 4 do
		local a, b, c, d = map[data:sub(i, i)], map[data:sub(i + 1, i + 1)], map[data:sub(i + 2, i + 2)], map[data:sub(i + 3, i + 3)]
		if not a or not b then break end
		local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
		n = n + 1 out[n] = string.char(math.floor(v / 65536) % 256)
		if c then n = n + 1 out[n] = string.char(math.floor(v / 256) % 256) end
		if d then n = n + 1 out[n] = string.char(v % 256) end
	end
	return table.concat(out)
end
local function logoImage()
	if logoAsset then return logoAsset end
	pcall(function()
		local b = getgenv().__WindyLogoB64
		if b and writefile and getcustomasset then
			writefile("WindyHub_logo.png", b64dec((b:gsub("%s", ""))))
			local a = getcustomasset("WindyHub_logo.png")
			if a and a ~= "" then logoAsset = a end
		end
	end)
	return logoAsset
end

