local function pulse()
	local btn = findBtnParts()
	if not btn then return end
	if WS.ring and WS.ring.Parent then WS.ring:Destroy() end
	local ring = Instance.new("Frame")
	ring.AnchorPoint = Vector2.new(0.5, 0.5) ring.Position = UDim2.new(0.5, 0, 0.5, 0) ring.Size = UDim2.new(0, 50, 0, 50)
	ring.BackgroundTransparency = 1 ring.ZIndex = 5 ring.Parent = btn
	WS.ring = ring
	local rc = Instance.new("UICorner") rc.CornerRadius = UDim.new(1, 0) rc.Parent = ring
	local st = Instance.new("UIStroke") st.Color = ACCENT st.Thickness = 2.5 st.Parent = ring
	TweenService:Create(ring, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = UDim2.new(0, 120, 0, 120) }):Play()
	TweenService:Create(st, TweenInfo.new(0.6, Enum.EasingStyle.Quad), { Transparency = 1 }):Play()
	task.delay(0.65, function() ring:Destroy() end)
end
-- kich thuoc menu: tu co gian theo man hinh (khong qua to / khong qua nho), luon tinh lai tu cong thuc co dinh
local function targetScale()
	local cam = workspace.CurrentCamera
	local v = cam and cam.ViewportSize or Vector2.new(1280, 720)
	local mobile = UIS.TouchEnabled and not UIS.KeyboardEnabled
	local pref = mobile and 1.0 or 1.45
	local fit = math.min((v.X - 24) / 629, (v.Y - 60) / 359)
	local s = math.min(pref, fit)
	return math.max(s, math.min(0.5, fit))
end
local function getMain()
	local gui = CoreGui:FindFirstChild("Windy Hub GUI")
	local main = gui and gui:FindFirstChild("Main")
	local sc = main and main:FindFirstChild("DeviceScale")
	return gui, main, sc
end
-- BO CHUYEN DONG: 1 bien tien do p (0 = an, 1 = hien). Bam nhieu lan chi doi huong, khong xung dot tween.
local anim = { p = 0, target = 0, rest = nil, conn = nil }
local function qOf(p) -- easeOutBack: hien thi no nhe, an thi nhun nhe roi tut xuong
	local x = p - 1
	return 1 + 2.4 * x * x * x + 1.4 * x * x
end
local function applyAnim()
	local gui, main, sc = getMain()
	if not (gui and main and sc) then return false end
	local q = qOf(anim.p)
	local rest = anim.rest or main.Position
	main.Position = UDim2.new(rest.X.Scale, rest.X.Offset, rest.Y.Scale + (1 - q) * 1.1, rest.Y.Offset)
	main.Rotation = (1 - q) * -9
	sc.Scale = targetScale() * (0.72 + 0.28 * q)
	return true
end
local function finishAnim()
	local gui, main, sc = getMain()
	WS.moving = false
	if not (gui and main and sc) then return end
	main.Rotation = 0
	if anim.rest then main.Position = anim.rest end
	sc.Scale = targetScale()
	gui.Enabled = anim.p >= 1
end
local function ensureLoop()
	if anim.conn then return end
	anim.conn = RunService.Heartbeat:Connect(function(dt)
		if anim.p == anim.target then return end
		local step = dt / (anim.target > anim.p and 0.55 or 0.4)
		if anim.target > anim.p then anim.p = math.min(anim.p + step, anim.target)
		else anim.p = math.max(anim.p - step, anim.target) end
		local gui = getMain()
		if not gui then anim.p = anim.target return end
		WS.moving = true
		gui.Enabled = true
		if not applyAnim() then anim.p = anim.target end
		if anim.p == anim.target then finishAnim() end
	end)
end
local lastPress = 0
lib.ToggleUI = function()
	local now = os.clock()
	if now - lastPress < 0.12 then return end -- chong bam qua nhanh
	lastPress = now
	local on = not getgenv().UIToggled
	getgenv().UIToggled = on
	pcall(function()
		local _, img, frame = findBtnParts()
		local sz = on and 46 or 40
		if WS.btnTw then for _, t in ipairs(WS.btnTw) do pcall(function() t:Cancel() end) end end
		WS.btnTw = {}
		if img then local t1 = TweenService:Create(img, TweenInfo.new(0.25), { Size = UDim2.new(0, sz, 0, sz) }) WS.btnTw[#WS.btnTw + 1] = t1 t1:Play() end
		if frame then local t2 = TweenService:Create(frame, TweenInfo.new(0.25), { BackgroundTransparency = on and 0 or 0.25 }) WS.btnTw[#WS.btnTw + 1] = t2 t2:Play() end
		pulse()
	end)
	local gui, main, sc = getMain()
	if not (gui and main and sc) then
		if gui then gui.Enabled = on end
		return
	end
	if anim.p == 0 or anim.p == 1 then anim.rest = main.Position end
	anim.target = on and 1 or 0
	blurTo(on and 14 or 0)
	ensureLoop()
end
