function api.Build()
	if built then return end
	built = true
	local frameT = os.clock()
	local function pace()
		if os.clock() - frameT > 0.012 then
			task.wait()
			frameT = os.clock()
		end
	end
	local okW, w = pcall(function()
		return lib:CreateWindow({ Title = "Windy Hub", Desc = "Blox Fruits  •  Việt Hoá", Image = logoImage(), DesktopScale = 1.45, MobileScale = 1.0 })
	end)
	if not okW or not w then
		warn("[Windy] CreateWindow loi -> giao dien du phong:", tostring(w))
		fb = __WindyFallbackUI()
		for _, t in ipairs(sortedTabs()) do
			local ft = fb.makeTab(t.name, t.title)
			for _, s in ipairs(sortedSecs(t)) do
				ft:UseSection(s.st)
				if s.st.title and s.st.title ~= "" then ft:AddSection(s.st.title) end
				for _, it in ipairs(s.items) do
					local o = it.o
					if it.kind == "toggle" then it.fb = ft:AddToggle({ Name = o.Name, Desc = o.Desc, Default = it.value, Callback = o.Callback })
					elseif it.kind == "slider" then it.fb = ft:AddSlider({ Name = o.Name, Min = it.min, Max = it.max, Default = it.value, Step = it.step, Callback = o.Callback })
					elseif it.kind == "button" then ft:AddButton({ Name = o.Name, Desc = o.Desc, Callback = o.Callback })
					elseif it.kind == "label" then it.fb = ft:AddLabel(it.text)
					elseif it.kind == "box" then it.fb = ft:AddBox({ Name = o.Name, Placeholder = o.Placeholder, Default = it.value, Numeric = o.Numeric, Callback = o.Callback })
					elseif it.kind == "dropdown" then it.fb = ft:AddDropdown({ Name = o.Name, Options = it.opts, Default = it.value, Callback = o.Callback })
					elseif it.kind == "multi" then
						local init = {}
						for n, on in pairs(it.sel) do if on then init[#init + 1] = n end end
						it.fb = ft:AddMultiDropdown({ Name = o.Name, Options = it.opts, Init = init, Priority = o.Priority, Callback = o.Callback })
					end
				end
			end
		end
		api.gui = fb.gui
		return
	end
	-- khoa kich thuoc: chi theo targetScale(), thu vien khong tu doi duoc nua
	do
		local _, _, sc0 = getMain()
		if sc0 then
			sc0.Scale = targetScale()
			sc0:GetPropertyChangedSignal("Scale"):Connect(function()
				if WS.moving then return end
				local tgt = targetScale()
				if math.abs(sc0.Scale - tgt) > 0.001 then sc0.Scale = tgt end
			end)
			local cam = workspace.CurrentCamera
			if cam then
				cam:GetPropertyChangedSignal("ViewportSize"):Connect(function()
					if not WS.moving then sc0.Scale = targetScale() end
				end)
			end
		end
	end
	for _, t in ipairs(sortedTabs()) do
		local okT, page = pcall(function() return w:AddTab(VT(t.name)) end)
		if okT and page then
			t.page = page
			for _, s in ipairs(sortedSecs(t)) do
				if #s.items > 0 then
					local title = (s.st.title and s.st.title ~= "") and s.st.title or t.name
					local okb, box = pcall(function() return page:AddLeftGroupbox(VT(title)) end)
					if okb and box then
						s.box = box
						for _, it in ipairs(s.items) do
							it.box = box
							realize(t, it)
							pace()
						end
					else
						warn("[Windy] AddLeftGroupbox loi:", title)
					end
				end
			end
		else
			warn("[Windy] AddTab loi:", t.name)
		end
	end
	api.gui = CoreGui:FindFirstChild("Windy Hub GUI")
	pcall(styleButton)
	task.delay(0.3, function()
		pcall(function()
			local T = getgenv().WindyTranslator
			if T and T.Reattach then T.Reattach() end
		end)
	end)
	-- mo menu voi hieu ung
	if not getgenv().UIToggled then lib.ToggleUI() end
end
api.makeTab = makeTab
api.selectTab = function() end
api.toggle = function() lib.ToggleUI() end
-- an toan: neu script khong bao hieu da tai xong thi van dung UI sau 120s
task.delay(120, function() pcall(api.Build) end)
return api
end)()

