		local R, m = 0, 1
		while f > 0 or K > 0 do
			local E, l = f % 2, K % 2
			f, K, R, m = (f - E) / 2, (K - l) / 2, (function() if E ~= l then return R + m else return R end end)(), m * 2
		end
		return R
	end
