BF_HopTried = BF_HopTried or {}
function BF_RegionOk(info)
	local region = Settings["Hop Server Region"]
	if not region or region == "Any" then
		return true
	end
	return type(info) == "table" and string.find(tostring(info.Region), region, 1, true) == 1
end
function BF_ServerNotFull(info)
	-- chi vao server co DUOI 10 nguoi (<= 9). Server tu 10 nguoi tro len -> bo qua. Khong biet so nguoi -> bo qua
	local c = type(info) == "table" and (tonumber(info.Count) or tonumber(info.count) or tonumber(info.Players) or tonumber(info.playing)) or nil
	if not c then
		return false
	end
	return c < 10
end
function HopServer(R, stop)
	local function shouldStop()
		if type(stop) ~= "function" then
			return false
		end
		local ok, r = pcall(stop)
		return ok and r and true or false
	end
	local function m()
		for E = 1, 100, 1 do
			if shouldStop() then
				return
			end
			local okL, list = pcall(function()
				return game:GetService("ReplicatedStorage").__ServerBrowser:InvokeServer(E)
			end)
			if not okL or type(list) ~= "table" then
				return
			end
			for l, Q in pairs(list) do
				if
					l ~= game.JobId
					and not table.find(CheckJobIdServer(), l)
					and BF_ServerNotFull(Q)
					and BF_RegionOk(Q)
					and tick() - (BF_HopTried[l] or 0) > 120
				then
					if shouldStop() then
						return
					end
					BF_HopTried[l] = tick()
					pcall(function()
						game:GetService("ReplicatedStorage").__ServerBrowser:InvokeServer("teleport", l)
					end)
					pcall(function()
						writefile("Windy Hub/Jobid.json", game:GetService("HttpService"):JSONEncode(K))
					end)
					pcall(function()
						getgenv().limit_type("clearAll")
					end)
					return -- 1 server moi lan, cho ket qua roi moi thu server khac
				end
			end
		end
	end
	local K = R or (Settings["Time Hop Server"] or 5)
	require(game:GetService("ReplicatedStorage").Notification)
		.new("<Color=Red>Windy Hub : Wait " .. K .. "s [Hop Server]<Color=/>")
		:Display()
	while wait(K) do
		if shouldStop() then
			return
		end
		require(game:GetService("ReplicatedStorage").Notification)
			.new("<Color=Red>Windy Hub : Hop Server<Color=/>")
			:Display()
		m()
	end
end

-- Hop 1 lan sang server ngau nhien (loc vung + so nguoi), dung cho Tyrant eyes
function BF_HopOnce()
	local browser = game:GetService("ReplicatedStorage"):FindFirstChild("__ServerBrowser")
	if not browser then
		return false
	end
	local blocked = {}
	pcall(function()
		for _, id in ipairs(CheckJobIdServer()) do
			blocked[id] = true
		end
	end)
	local pool = {}
	for page = 1, 100 do
		local ok, list = pcall(function()
			return browser:InvokeServer(page)
		end)
		if not ok or type(list) ~= "table" then
			break
		end
		for id, info in pairs(list) do
			if id ~= game.JobId and not blocked[id] and BF_ServerNotFull(info) and BF_RegionOk(info) and tick() - (BF_HopTried[id] or 0) > 120 then
				pool[#pool + 1] = id
			end
		end
		if #pool >= 30 then
			break
		end
	end
	while #pool > 0 do
		local id = table.remove(pool, math.random(#pool))
		BF_HopTried[id] = tick()
		if pcall(function() browser:InvokeServer("teleport", id) end) then
			pcall(function() getgenv().limit_type("clearAll") end)
			return true
		end
	end
	return false
end
-- Tyrant: dem mat con thieu (Eye1..4 trong TikiOutpost), nhieu hon slider thi hop
function HopLessEyesTyrant()
	if game.PlaceId ~= getgenv().CheckPlaceId then
		return false
	end
	local nextHop = getgenv().__BF_NextEyesHop
	if nextHop and os.clock() < nextHop then
		return false
	end
	if CheckNameBoss("Tyrant of the Skies") then
		return false
	end
	if type(CheckIsplayingRaid) == "function" and CheckIsplayingRaid() then
		return false
	end
	local map = workspace:FindFirstChild("Map")
	local tiki = map and map:FindFirstChild("TikiOutpost")
	local island = tiki and tiki:FindFirstChild("IslandModel")
	if not island then
		return false
	end
	local missing = 0
	for i = 1, 4 do
		local eye = island:FindFirstChild("Eye" .. i, true)
		if not eye then
			return false
		end
		if eye.Transparency == 1 then
			missing = missing + 1
		end
	end
	if missing <= math.floor(tonumber(Settings["Max Missing Tyrant Eyes"]) or 0) then
		return false
	end
	getgenv().__BF_NextEyesHop = os.clock() + 15
	return BF_HopOnce()
end
