SectionLocalPlayerMain.CreateButton({ Title = "Show/Hide Floating Stop Tween" }, function()
	local env = getgenv()
	local old = env.__BF_StopTweenGui
	if old and old.Parent then
		pcall(function() old:Destroy() end)
		env.__BF_StopTweenGui = nil
		return
	end
	local UIS = game:GetService("UserInputService")
	local gui = Instance.new("ScreenGui")
	gui.Name = "BF_StopTween"
	gui.ResetOnSpawn = false
	gui.DisplayOrder = 999
	local okParent = pcall(function()
		gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
	end)
	if not okParent or not gui.Parent then
		gui.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
	end
	env.__BF_StopTweenGui = gui
	local btn = Instance.new("TextButton")
	btn.Name = "StopTween"
	btn.Size = UDim2.new(0, 110, 0, 38)
	btn.Position = UDim2.new(0.5, -55, 0.3, 0)
	btn.BackgroundColor3 = Color3.fromRGB(35, 35, 35)
	btn.TextColor3 = Color3.new(1, 1, 1)
	btn.Font = Enum.Font.GothamBold
	btn.TextSize = 14
	btn.Text = "Stop Tween"
	btn.AutoButtonColor = true
	btn.Parent = gui
	local corner = Instance.new("UICorner")
	corner.CornerRadius = UDim.new(0, 8)
	corner.Parent = btn
	local dragStart, startPos, dragInput, moved = nil, nil, nil, false
	btn.InputBegan:Connect(function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		dragStart, startPos, dragInput, moved = input.Position, btn.Position, input, false
	end)
	btn.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)
	local c1 = UIS.InputChanged:Connect(function(input)
		if not dragStart or input ~= dragInput then
			return
		end
		local delta = input.Position - dragStart
		if delta.Magnitude > 5 then
			moved = true
			btn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
		end
	end)
	local c2 = UIS.InputEnded:Connect(function(input)
		if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragStart = nil
		end
	end)
	btn.Activated:Connect(function()
		if moved then
			return
		end
		pcall(function()
			getgenv().noclip = false
			if TweenManager.ForceRelease then
				TweenManager.ForceRelease()
				return
			end
			TweenManager.CancelCurrent()
		end)
	end)
	gui.Destroying:Connect(function()
		pcall(function() c1:Disconnect() end)
		pcall(function() c2:Disconnect() end)
	end)
end)
