do
	if getgenv().__BackMonConn then
		pcall(function() getgenv().__BackMonConn:Disconnect() end)
	end
	local last
	getgenv().__BackMonConn = x.Heartbeat:Connect(function()
		local ch = t.Character
		local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
		if not hrp then
			last = nil
			return
		end
		local pos, now, cs = hrp.Position, tick(), H()
		if cs.cap > 1000 then cs.cap = 450 end
		if now - (k.LastTP or 0) < 0.6 and k.LastCF and last then
			local d = pos - last
			local toward = k.LastCF.Position - last
			if d.Magnitude > 30 and toward.Magnitude > 8 and d:Dot(toward) < 0 then
				cs.cap = math.max(cs.cap * 0.6, 200)
				cs.nextRaise = now + 4
				pcall(function()
					TweenManager.CancelTweenOnly()
					hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
				end)
			elseif now >= (cs.nextRaise or 0) and cs.user and cs.cap < cs.user and toward.Magnitude > 60 then
				cs.cap = math.min(cs.cap * 1.15, cs.user)
				cs.nextRaise = now + 0.5
			end
		end
		last = pos
	end)
end
-- Tween người chơi: logic TweenService Linear giống TweenTo của Topi SeaEvent
-- (dùng lại TweenManager.PlayTween có sẵn: hủy tween cũ, dedupe theo đích)
local function B(Z, C, J, F, skipBoat)
	if not Z or typeof(C) ~= "CFrame" then
		return
	end
	local char = t.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not char or Z.Parent ~= char or not hum or hum.Health <= 0 or Z.Anchored then
		return
	end

	J = math.max(tonumber(J) or 350, 1) -- speed (stud/s)
	do
		local cs = H()
		cs.user = J
		if not (ReadyToDodge or getgenv().DodgeDescend) then
			J = math.min(J, cs.cap)
		end
	end
	F = tonumber(F) or 2.5 -- epsilon

	-- [BoatTween] toggle "Use Boat Tween": chang xa -> mua thuyen, ngoi, tween thuyen toi gan dich
	if not skipBoat and Settings["Use Boat Tween"] and getgenv().BoatTween then
		local okb, handled = pcall(getgenv().BoatTween.Hook, Z, C, J, F, B, G or ReadyToDodge)
		if not okb and type(WarnOnce) == "function" then
			WarnOnce("BoatTweenErr", "[BoatTween] " .. tostring(handled))
		end
		if okb and handled then
			return
		end
	end

	-- chi tween vi tri, giu nguyen huong hien tai cua nguoi choi
	C = CFrame.new(C.Position) * (Z.CFrame - Z.CFrame.Position)
	k.LastTP, k.LastCF = tick(), C

	local dist = (C.Position - Z.Position).Magnitude
	if dist <= F then
		-- đã sát đích -> snap luôn
		TweenManager.CancelTweenOnly()
		I()
		Z.CFrame = C
		Z.AssemblyLinearVelocity = Vector3.zero
		Z.AssemblyAngularVelocity = Vector3.zero
		return
	end

	I() -- tag "Teleporting"
	getgenv().noclip = true

	local tw = TweenManager.PlayTween(
		Z,
		TweenInfo.new(math.max(dist / J, 0.05), Enum.EasingStyle.Linear, Enum.EasingDirection.InOut),
		{ CFrame = C },
		{ TargetEpsilon = math.max(F, 6) }
	)

	-- giữ tag Teleporting trong lúc tween chạy + reset vận tốc khi xong
	if tw and TweenManager.__keepFor ~= tw then
		TweenManager.__keepFor = tw
		task.spawn(function()
			while TweenManager.currentTween == tw do
				I()
				task.wait(0.1)
			end
			pcall(function()
				Z.AssemblyLinearVelocity = Vector3.zero
				Z.AssemblyAngularVelocity = Vector3.zero
			end)
		end)
	end
	return tw
end

-- ===================== [BoatTween] Use Boat Tween =====================
-- Hook nam trong B (tween nguoi choi) nen ap dung cho ca dich cuoi lan tele trung gian.
--  * Muc tieu cach > 500 stud (mat phang ngang) va dich khong nam trong 1000 stud cua Boat Dealer gan nhat -> mua thuyen
--  * Tween toi Boat Dealer gan nhat -> BuyBoat -> ngoi vao -> tween thuyen toi dich
--  * Con cach dich <= 500 stud -> nhay xuong, tween thuong de farm
--  * Chi tac dong khi chinh no dang cam thuyen (session). Thuyen cua cac tinh nang khac khong bi dung toi
getgenv().BoatTween = (function()
	local BOAT_NAME = "PirateGrandBrigade" -- ten remote cua GrandBrigade (khop voi code Sea Event)
	local DEALER_KEY = "Boat Dealer"
	local DISMOUNT_DIST = 500 -- con cach dich bay nhieu thi nhay xuong
	local DEALER_SKIP_DIST = 1000 -- dich gan dealer <= 1000 thi khong mua
	local REUSE_DIST = 300 -- thuyen cua minh o gan hon muc nay thi dung lai, khong mua moi
	local lp = game:GetService("Players").LocalPlayer
	local RS = game:GetService("ReplicatedStorage")
	local VIM = game:GetService("VirtualInputManager")
	local st = { busy = false, session = nil, riding = false, seaY = nil, cool = 0, drive = 0, sitUntil = 0, dealers = {}, scanAt = 0 }
	local M = {}

	local function flat(a, b)
		return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
	end
	-- thuyen khong di duoc: tren troi, duoi nuoc sau, vung X > 40000
	local function zoneOk(p)
		return p.Y > -100 and p.Y < 1500 and p.X < 40000
	end

	local function scanDealers()
		if tick() < st.scanAt then
			return st.dealers
		end
		st.scanAt = tick() + 3
		local list = {}
		for _, folder in ipairs({ workspace:FindFirstChild("NPCs"), RS:FindFirstChild("NPCs") }) do
			if folder then
				for _, n in ipairs(folder:GetChildren()) do
					if n.Name:find(DEALER_KEY, 1, true) and not n.Name:find("Luxury", 1, true) then
						local ok, pos = pcall(function()
							local r = n:FindFirstChild("HumanoidRootPart")
							return r and r.Position or n:GetPivot().Position
						end)
						if ok and pos then
							list[#list + 1] = pos
						end
					end
				end
			end
		end
		if #list > 0 then
			st.dealers = list
		end
		return st.dealers
	end

	local function nearestDealer(pos)
		local best, bd
		for _, d in ipairs(scanDealers()) do
			local m = (d - pos).Magnitude
			if not bd or m < bd then
				best, bd = d, m
			end
		end
		return best, bd
	end

	-- thuyen cua minh (gan nearPos nhat, trong maxDist neu co)
	local function myBoat(nearPos, maxDist)
		local boats = workspace:FindFirstChild("Boats")
		if not boats then
			return
		end
		local best, bd
		for _, b in ipairs(boats:GetChildren()) do
			if b:IsA("Model") then
				local o, h, seat = b:FindFirstChild("Owner"), b:FindFirstChild("Humanoid"), b:FindFirstChild("VehicleSeat")
				if o and seat and tostring(o.Value) == lp.Name and (not h or h.Value > 0) then
					local m = nearPos and (seat.Position - nearPos).Magnitude or 0
					if (not maxDist or m <= maxDist) and (not bd or m < bd) then
						best, bd = b, m
					end
				end
			end
		end
		return best
	end

	-- dich la thuyen / gan thuyen (ghe, engine, thuyen dich...) -> de cac tinh nang khac tu xu ly
	local function nearAnyBoat(p)
		local boats = workspace:FindFirstChild("Boats")
		if boats then
			for _, b in ipairs(boats:GetChildren()) do
				local ok, pv = pcall(function()
					return b:GetPivot().Position
				end)
				if ok and (pv - p).Magnitude < 150 then
					return true
				end
			end
		end
		return false
	end

	local function cancelBoat()
		local tb = getgenv().TweenBoat
		if tb then
			pcall(function()
				tb:Cancel()
			end)
		end
	end

	local function clearSession()
		st.session, st.riding, st.seaY = nil, false, nil
	end

	local function dismount(hum, hrp)
		cancelBoat()
		clearSession()
		pcall(function()
			VIM:SendKeyEvent(true, "Space", false, game)
			task.wait()
			VIM:SendKeyEvent(false, "Space", false, game)
		end)
		hum.Jump = true
		local t0 = tick()
		while hum.SeatPart and tick() - t0 < 1 do
			task.wait()
		end
		if hum.SeatPart then
			hum.Sit = false
		end
		task.wait(0.1)
		if hrp.Parent then
			hrp.CFrame = hrp.CFrame * CFrame.new(0, 10, 0)
		end
		-- tra lai va cham / tat noclip (giong nhanh Sit goc cua toTarget)
		getgenv().noclip = false
		pcall(function()
			for _, p in ipairs(lp.Character:GetDescendants()) do
				if p:IsA("BasePart") then
					p.CanCollide = true
				end
			end
		end)
		TweenManager.CancelCurrent()
	end

	-- toTarget dung de biet co nen giu nguoi choi tren thuyen (khong nhay xuong) hay khong
	function M.OwnsSeat(hum)
		local b = st.session
		if not b or not hum or not b.Parent then
			return false
		end
		local seat = hum.SeatPart
		if not (seat and seat.Parent == b) then
			return false
		end
		-- lau khong co lenh tween nao (vd. luong khac dang xu ly rieng) -> tra quyen cho toTarget
		return tick() - st.drive < 4
	end

	function M.Reset()
		cancelBoat()
		clearSession()
		st.busy = false
		st.cool = 0
	end

	-- tra true = da xu ly (B khong tween nguoi choi nua)
	function M.Hook(hrp, cf, speed, eps, B, dodge)
		if dodge or not Settings["Use Boat Tween"] then
			return false
		end
		local char = lp.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not hum or hum.Health <= 0 or hrp.Parent ~= char then
			return false
		end
		if st.busy then
			return true
		end
		local tpos, hp = cf.Position, hrp.Position
		local seat = hum.SeatPart
		if st.session and not st.session.Parent then
			clearSession()
		end

		-- A. dang ngoi tren thuyen cua session -> tween thuyen
		if st.session and seat and seat.Parent == st.session then
			st.riding, st.drive = true, tick()
			st.seaY = st.seaY or seat.Position.Y
			local ff = hrp:FindFirstChild("FloatForce")
			if ff then
				ff:Destroy()
			end
			TweenManager.CancelTweenOnly()
			if flat(seat.Position, tpos) <= DISMOUNT_DIST or not zoneOk(tpos) then
				st.busy = true
				pcall(dismount, hum, hrp)
				st.busy = false
				return true
			end
			local bspeed = tonumber(Settings["Value Speed Tween Boat"]) or 350
			pcall(
				manageTween,
				seat,
				CFrame.new(tpos.X, st.seaY, tpos.Z) * (seat.CFrame - seat.Position),
				bspeed,
				"TweenBoat"
			)
			return true
		end

		-- B. khong ngoi tren thuyen cua session
		if st.riding then
			clearSession() -- vua xuong thuyen
		end
		if seat then
			return false -- dang ngoi cho khac (thuyen cua tinh nang khac...)
		end
		if flat(hp, tpos) <= DISMOUNT_DIST then
			clearSession()
			return false
		end
		if tick() < st.cool or not zoneOk(hp) or not zoneOk(tpos) or nearAnyBoat(tpos) then
			return false
		end

		local pspeed = math.max(tonumber(Settings["Speed Tween "]) or 190, 1)
		local bspeed = math.max(tonumber(Settings["Value Speed Tween Boat"]) or 350, 1)
		local boat = st.session or myBoat(hp, REUSE_DIST)
		local bseat = boat and boat:FindFirstChild("VehicleSeat")
		local dealer
		if not bseat then
			boat = nil
			dealer = nearestDealer(hp)
			if not dealer or flat(dealer, tpos) <= DEALER_SKIP_DIST then
				return false
			end
		end

		-- chi tinh loi/lo luc moi bat dau (da vao session thi di tiep)
		if not st.session then
			local pick = bseat and bseat.Position or dealer
			local tDirect = flat(hp, tpos) / pspeed
			local tBoat = flat(hp, pick) / pspeed
				+ (bseat and 0 or 4)
				+ math.max(flat(pick, tpos) - DISMOUNT_DIST, 0) / bspeed
				+ DISMOUNT_DIST / pspeed
			if tBoat >= tDirect then
				return false
			end
		end

		if bseat then
			-- ra ghe thuyen, cham vao la tu ngoi
			if st.session ~= boat then
				st.session, st.riding, st.seaY, st.sitUntil = boat, false, nil, tick() + 20
			elseif tick() > st.sitUntil then
				clearSession()
				st.cool = tick() + 30
				return false
			end
			st.drive = tick() -- giu quyen OwnsSeat luc vua ngoi vao, neu khong toTarget se nhay xuong ngay
			B(hrp, bseat.CFrame, pspeed, 4, true)
			return true
		end

		-- toi Boat Dealer gan nhat
		if (hp - dealer).Magnitude > 15 then
			B(hrp, CFrame.new(dealer), pspeed, 8, true)
			return true
		end
		-- toi noi -> mua thuyen
		st.busy = true
		TweenManager.CancelTweenOnly()
		pcall(function()
			RS.Remotes.CommF_:InvokeServer("BuyBoat", BOAT_NAME)
		end)
		local t0, nb = tick(), nil
		repeat
			task.wait(0.25)
			nb = myBoat(dealer, 400)
		until nb or tick() - t0 > 6
		st.busy = false
		if not nb then
			st.cool = tick() + 20
			if type(WarnOnce) == "function" then
				WarnOnce("BoatTweenBuy", "[BoatTween] Mua thuyen that bai (thieu tien / sai ten boat?). Tween thuong 20s.")
			end
			return false
		end
		st.session, st.riding, st.seaY, st.sitUntil = nb, false, nil, tick() + 20
		st.drive = tick()
		return true
	end

	return M
end)()
-- =====================================================================

do
	local Sea1Gate = {}
	getgenv().Sea1Gate = Sea1Gate
	local Sea2Gate = {}
	getgenv().Sea2Gate = Sea2Gate
	local CFG = {
		SKY2_POS = Vector3.new(-4210, 1092, -374),
		SKY_START_POS = Vector3.new(-6022, 5485, 2222),
		SKY_ENTRANCE_POS = Vector3.new(-4166.60986328125, 1093.697998046875, -347.16226196289062),
		UNDER_WAIT_POS = Vector3.new(4047, 10, -1816),
		UNDER_ENTRANCE_POS = Vector3.new(61163.8515625, 11.680007934570312, 1819.7840576171875),
		XOAY_WAIT_POS = Vector3.new(61170, 10, 1955),
		XOAY_ENTRANCE_POS = Vector3.new(3864.68798828125, 6.73699951171875, -1926.2139892578125),
		SKY3_Y = 4000,
		UNDER_X = 40000,
		CLOUD_RANGE = 50,
		CLOUD_REACH = 10,
		CLOUD_ENTRANCE_POS = Vector3.new(-6023.57666015625, 5469.7197265625, 2203.308349609375),
		CLOUD_SKIP_TIME = 10,
		CLOUD_INTERVAL = 0.1,
	}
	local st = { lastClick = 0, arrivedAt = nil, lastEntrance = 0, cloudSkip = setmetatable({}, { __mode = "k" }) }

	local function zoneOf(pos)
		if pos.X > CFG.UNDER_X then
			return "Under"
		end
		if pos.Y > CFG.SKY3_Y then
			return "Sky3"
		end
		return "Main"
	end

	local function flyTo(H, pos)
		B(H, CFrame.new(pos), tonumber(Settings["Speed Tween "]) or 190, 8)
	end

	local function cloudPos(obj)
		if obj:IsA("BasePart") then
			return obj.Position
		elseif obj:IsA("Model") then
			return obj:GetPivot().Position
		end
	end

	local CLICK_UDIM = UDim2.new(0.15, 0, 0.15, 0)
	local function doClick()
		local vim = game:GetService("VirtualInputManager")
		local vp = workspace.CurrentCamera.ViewportSize
		local x = vp.X * CLICK_UDIM.X.Scale + CLICK_UDIM.X.Offset
		local y = vp.Y * CLICK_UDIM.Y.Scale + CLICK_UDIM.Y.Offset
		vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
		vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
	end

	local function pickCloud(hrp)
		local map = workspace:FindFirstChild("Map")
		local sky = map and map:FindFirstChild("Sky")
		if not sky then
			return nil
		end
		local now = tick()
		local best, bestD
		for _, obj in ipairs(sky:GetChildren()) do
			if obj.Name:lower() == "cloud" and (st.cloudSkip[obj] or 0) < now then
				local pos = cloudPos(obj)
				if pos and (pos - CFG.SKY2_POS).Magnitude <= CFG.CLOUD_RANGE then
					local d = (pos - hrp.Position).Magnitude
					if not bestD or d < bestD then
						best, bestD = obj, d
					end
				end
			end
		end
		return best
	end

	local function gate(H, waitPos, entrancePos, delay, after)
		if tick() < (st.cool or 0) then
			return false
		end
		if (H.Position - waitPos).Magnitude > 15 then
			st.arrivedAt = nil
			flyTo(H, waitPos)
			return true
		end
		local now = tick()
		if not st.arrivedAt then
			st.arrivedAt = now
			return true
		end
		if now - st.arrivedAt < 0.3 or now - st.lastEntrance < 1.5 then
			return true
		end
		if not st.attemptStart or now - st.attemptStart > 60 then
			st.attemptStart, st.attempts = now, 0
		end
		st.attempts = st.attempts + 1
		if st.attempts > 5 then
			st.cool, st.arrivedAt, st.attemptStart = now + 30, nil, nil
			return false
		end
		BuddhaOffBeforeRemote(I) -- tới pos trung gian: tắt Phật (giữ fly) rồi mới chạy remote
		st.lastEntrance = now
		local before = H.Position
		local t0 = tick()
		while tick() - t0 < 20 do
			k.LastCall = tick()
			I()
			pcall(function()
				game.ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", entrancePos)
			end)
			task.wait(0.2)
			local hrp = getHRP()
			if not hrp or (hrp.Position - before).Magnitude > 100 then
				break
			end
		end
		st.lastEntrance = tick()
		if after then
			pcall(after)
		end
		return true
	end

	local function startClickLoop()
		if st.clicking then
			return
		end
		st.clicking = true
		getgenv().Sky3Climbing = true
		task.spawn(function()
			local lp = game:GetService("Players").LocalPlayer
			local lastEquip = 0
			local target
			while tick() - (st.climbTick or 0) < 0.6 do
				local hrp = getHRP()
				if not hrp or hrp.Position.Y > CFG.SKY3_Y then
					break
				end
				if tick() - lastEquip >= 0.5 and not getgenv().BuddhaRemoteHold then
					lastEquip = tick()
					pcall(function()
						local char = lp.Character
						local hum = char and char:FindFirstChildOfClass("Humanoid")
						local tool = NameWeapon and NameWeapon("Melee", true)
						if hum and tool and not hum.Sit and tool.Parent ~= char then
							hum:EquipTool(tool)
						end
					end)
				end
				if not target or not target.Parent then
					target = pickCloud(hrp)
				end
				local pos = target and cloudPos(target)
				if pos then
					if (hrp.Position - pos).Magnitude > CFG.CLOUD_REACH then
						flyTo(hrp, pos)
					else
						BuddhaOffBeforeRemote(I) -- tắt Phật trước khi click mây + requestEntrance
						st.cloudSkip[target] = tick() + CFG.CLOUD_SKIP_TIME
						target = nil
						pcall(doClick)
						task.wait(0.15)
						I()
						pcall(function()
							game.ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", CFG.CLOUD_ENTRANCE_POS)
						end)
						task.wait(0.3)
					end
				else
					target = nil
					if (hrp.Position - CFG.SKY2_POS).Magnitude > 15 then
						flyTo(hrp, CFG.SKY2_POS)
					end
				end
				task.wait(CFG.CLOUD_INTERVAL)
			end
			getgenv().Sky3Climbing = false
			st.clicking = false
		end)
	end

	local function climbSky3(H)
		st.climbTick = tick()
		if st.clicking then
			return true
		end
		local d = (H.Position - CFG.SKY2_POS).Magnitude
		if d > 60 then
			flyTo(H, CFG.SKY2_POS)
		else
			startClickLoop()
		end
		return true
	end

	function Sea1Gate.Step(H, targetPos)
		local pz, tz = zoneOf(H.Position), zoneOf(targetPos)
		if pz == tz then
			st.arrivedAt = nil
			return false
		end
		getgenv().noclip = true
		if pz == "Under" then
			return gate(H, CFG.XOAY_WAIT_POS, CFG.XOAY_ENTRANCE_POS, 0.6)
		elseif pz == "Sky3" then
			return gate(H, CFG.SKY_START_POS, CFG.SKY_ENTRANCE_POS, 0.7, function()
				local hrp = getHRP()
				if hrp and hrp.Position.Y < CFG.SKY3_Y then
					hrp.CFrame = hrp.CFrame + Vector3.new(0, 30, 0)
				end
			end)
		elseif tz == "Sky3" then
			return climbSky3(H)
		elseif tz == "Under" then
			return gate(H, CFG.UNDER_WAIT_POS, CFG.UNDER_ENTRANCE_POS, 0.6)
		end
		return false
	end

	local C2 = {
		MANSION_WAIT = Vector3.new(-287, 328, 591),
		MANSION_ENTRANCE = Vector3.new(-286.9859619140625, 306.13739013671875, 597.8905029296875),
		ROOM_WAIT = Vector3.new(2285, 42, 911),
		ROOM_ENTRANCE = Vector3.new(2284.9091796875, 15.537796020507812, 905.4727783203125),
		MANSION_R = 900,
		MANSION_MIN_Y = 200,
		ROOM_R = 600,
		DOOR_WAIT = Vector3.new(-6498, 106, -119),
		SHIP_ENTRANCE = Vector3.new(923.2130126953125, 126.97599792480469, 32852.83203125),
		SHIP_WAIT = Vector3.new(923, 125, 32853),
		DOOR_ENTRANCE = Vector3.new(-6508.55810546875, 89.035003662109375, -132.83999633789062),
		SHIP_Z = 20000,
	}

	local SHIP_FLAG = nil

	local function horiz(a, b)
		return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
	end

	local function flamZone(pos)
		if pos.Y > C2.MANSION_MIN_Y and horiz(pos, C2.MANSION_WAIT) < C2.MANSION_R then
			return "Mansion"
		end
		if horiz(pos, C2.ROOM_WAIT) < C2.ROOM_R then
			return "Room"
		end
		return nil
	end

	local function lift(cond, dy)
		return function()
			local hrp = getHRP()
			if hrp and cond(hrp.Position) then
				hrp.CFrame = hrp.CFrame + Vector3.new(0, dy, 0)
			end
		end
	end

	function Sea2Gate.Step(H, targetPos)
		local pos = H.Position
		local pShip, tShip = pos.Z > C2.SHIP_Z, targetPos.Z > C2.SHIP_Z

		if pShip ~= tShip then
			if SHIP_FLAG and not getgenv().IsUnlocked(SHIP_FLAG) then
				return false
			end
			getgenv().noclip = true
			if tShip then
				return gate(H, C2.DOOR_WAIT, C2.SHIP_ENTRANCE, 0.6, lift(function(p)
					return p.Z > C2.SHIP_Z
				end, 60))
			end
			return gate(H, C2.SHIP_WAIT, C2.DOOR_ENTRANCE, 0.6, lift(function(p)
				return p.Z < C2.SHIP_Z
			end, 30))
		end
		if pShip then
			st.arrivedAt = nil
			return false
		end

		if not getgenv().IsUnlocked("FlamingoAccess") then
			return false
		end
		local tz = flamZone(targetPos)
		if tz then
			local dM = (pos - C2.MANSION_WAIT).Magnitude
			local dR = (pos - C2.ROOM_WAIT).Magnitude
			if tz == "Mansion" and dR < dM then
				getgenv().noclip = true
				return gate(H, C2.ROOM_WAIT, C2.MANSION_ENTRANCE, 0.6, lift(function(p)
					return flamZone(p) == "Mansion"
				end, 30))
			elseif tz == "Room" and dM < dR then
				getgenv().noclip = true
				return gate(H, C2.MANSION_WAIT, C2.ROOM_ENTRANCE, 0.6, lift(function(p)
					return flamZone(p) == "Room"
				end, 30))
			end
		end
		st.arrivedAt = nil
		return false
	end
end

do
	local Sea3Gate = {}
	getgenv().Sea3Gate = Sea3Gate
	local V3 = Vector3.new

	getgenv().ShortcutWorth = function(direct, viaFly, overheadSec)
		local speed = tonumber(Settings["Speed Tween "]) or 190
		local margin = tonumber(getgenv().Sea3RouteMargin) or 0
		return viaFly + (overheadSec or 0) * speed + margin < direct
	end

	local HOP = {
		["Castle>Hydra"] = { to = "Hydra", fly = V3(-5027.0302734375, 330, -3206.70361328125), ent = V3(5662, 1013, -338), need = "indra" },
		["Hydra>Castle"] = { to = "Castle", fly = V3(5659, 1030, -334), ent = V3(-5021, 314, -3194), need = "indra" },
		["Mansion>Castle"] = { to = "Castle", fly = V3(-12463.6025390625, 398, -7566.0830078125), ent = V3(-5055, 314, -3179), need = "indra" },
		["Castle>Mansion"] = { to = "Mansion", fly = V3(-5060.41162109375, 330, -3193.224853515625), ent = V3(-12465, 374, -7554), need = "indra" },
		["Tiki>Castle"] = { to = "Castle", fly = V3(-16800, 59, 291), jump = "Castle", need = "tiki" },
		["Castle>Tiki"] = { to = "Tiki", fly = V3(-5098, 316, -3179), jump = "Tiki", need = "tiki" },
		["Tiki>Submerged"] = { to = "Submerged", fly = V3(-16269.4082, 23.9799957, 1371.66235), sub = true, need = "tiki" },
	}
	local LIFT = 100

	local REFS = {
		Hydra = { V3(3399, 72, 1572), V3(5245, 602, 251), V3(5288, 1011, 392), V3(5661, 1013, -334), V3(5659, 1030, -334) },
		Castle = { V3(-5500, 314, -2855), V3(-5055, 314, -3179), V3(-5027, 318, -3206), V3(-5060, 330, -3193), V3(-5098, 316, -3179) },
		Mansion = {
			V3(-12463, 375, -7549), V3(-12548, 337, -7481), V3(-12463.6, 398, -7566),
			V3(-12538, 339, -7817),
			V3(-12008, 339, -9179),
			V3(-10164, 340, -8321),
			V3(-12857, 853, -10715),
		},
		Tiki = { V3(-16204, 9, 479), V3(-16456, 530, 436), V3(-16800, 59, 291) },
	}
	local function minDist(pos, refs)
		local m = math.huge
		for _, r in ipairs(refs) do
			local d = (pos - r).Magnitude
			if d < m then
				m = d
			end
		end
		return m
	end

	local function nearestHub(pos)
		local best, bd
		for name, refs in pairs(REFS) do
			local d = minDist(pos, refs)
			if not bd or d < bd then
				best, bd = name, d
			end
		end
		return best, bd
	end

	local function hubOpen(name)
		if name == "Castle" then
			return true
		end
		local need = HOP["Castle>" .. name].need
		if need == "indra" then
			return getgenv().IsUnlocked("DefeatedIndraTrueForm")
		end
		if need == "tiki" then
			return getgenv().IsTikiBossKilled()
		end
		return true
	end

	local function nearestOpenHub(pos)
		local best, bd
		for name, refs in pairs(REFS) do
			if hubOpen(name) then
				local d = minDist(pos, refs)
				if not bd or d < bd then
					best, bd = name, d
				end
			end
		end
		return best
	end

	local SUB_ISLANDS = {
		["Turtle Mountain"] = V3(-9537, 7, -8348),
		["Hydra Town"] = V3(3251, 5, 2431),
		["Chocolate Land"] = V3(-155, 7, -11938),
		["Sea Castle"] = V3(-6071, 16, -2155),
		["Haunted Castle"] = V3(-9517, 20, 4565),
		["Port"] = V3(6, 10, 5397),
		["Peanut Land"] = V3(-2041, 4, -9826),
		["Great Tree"] = V3(2041, 21, -6525),
		["Ice Cream Land"] = V3(-1007, 7, -10745),
		["Cake Land"] = V3(-1989, 9, -11411),
	}

	local CAKE_ARENA = Vector3.new(-1990.67, 4532.97, -14973.67)
	local function nearestNode(pos, onlyOpen)
		if (pos - CAKE_ARENA).Magnitude <= 1000 then
			return "Cake Land"
		end
		local best, bd
		for name, p in pairs(SUB_ISLANDS) do
			local d = (pos - p).Magnitude
			if not bd or d < bd then
				best, bd = name, d
			end
		end
		for name, refs in pairs(REFS) do
			if not onlyOpen or hubOpen(name) then
				local d = minDist(pos, refs)
				if not bd or d < bd then
					best, bd = name, d
				end
			end
		end
		return best
	end

	getgenv().SubmarineDest = function(pos)
		if not Settings["Use Submarine Teleport"] then
			return nil
		end
		if not getgenv().IsTikiBossKilled() then
			return nil
		end
		local best = nearestNode(pos, true)
		if SUB_ISLANDS[best] then
			return best
		end
		return nil
	end

	local function route(ph, dh)
		local hops = {}
		if ph ~= "Castle" then
			hops[#hops + 1] = ph .. ">Castle"
		end
		if dh ~= "Castle" then
			hops[#hops + 1] = "Castle>" .. dh
		end
		return hops
	end

	local running, cancelled, cool, fails = false, false, 0, 0

	local function dbg(...)
		if getgenv().DebugSea3 then
			print("[Sea3]", ...)
		end
	end
	local lastWhy = 0
	local function why(msg)
		if getgenv().DebugSea3 and tick() - lastWhy > 3 then
			lastWhy = tick()
			print("[Sea3] bỏ qua cổng:", msg)
		end
	end

	local function alive()
		k.LastCall = tick()
		getgenv().noclip = true
		I()
	end

	local function hold(t)
		local t0 = tick()
		while tick() - t0 < t do
			if cancelled then
				return
			end
			alive()
			task.wait(0.1)
		end
	end

	local function flyTo(pos, radius, timeout)
		radius = radius or 15
		local t0 = tick()
		while tick() - t0 < (timeout or 90) do
			if cancelled then
				return false
			end
			local hrp = getHRP()
			if not hrp then
				return false
			end
			if (hrp.Position - pos).Magnitude < radius then
				return true
			end
			alive()
			B(hrp, CFrame.new(pos), tonumber(Settings["Speed Tween "]) or 190, 8)
			task.wait(0.15)
		end
		dbg("flyTo timeout/huỷ", pos)
		return false
	end

	local function doJump()
		local ch = game:GetService("Players").LocalPlayer.Character
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if not hum then
			return
		end
		alive()
		hum.Jump = true
		pcall(function()
			hum:ChangeState(Enum.HumanoidStateType.Jumping)
		end)
		local vim = game:GetService("VirtualInputManager")
		vim:SendKeyEvent(true, "Space", false, game)
		task.wait(0.1)
		vim:SendKeyEvent(false, "Space", false, game)
	end

	local function jumpUntilNear(name, timeout)
		local t0 = tick()
		while tick() - t0 < (timeout or 25) do
			if cancelled then
				return false
			end
			local hrp = getHRP()
			if not hrp then
				return false
			end
			if nearestHub(hrp.Position) == name then
				dbg("đã gần", name, "sau", math.floor((tick() - t0) * 10) / 10, "s")
				return true
			end
			dbg("chưa gần", name, "(đang gần", nearestHub(hrp.Position) .. ") -> nhảy")
			doJump()
			hold(0.6)
		end
		dbg("nhảy timeout, vẫn chưa tới", name)
		return false
	end

	local function runHop(h)
		dbg("hop ->", h.to, "bay tới", h.fly)
		if not flyTo(h.fly) then
			return false
		end
		hold(h.jump and 0.6 or 0.3)
		if h.sub or h.ent then
			BuddhaOffBeforeRemote(alive) -- tới pos trung gian: tắt Phật trước khi chạy remote
		end
		if h.sub then
			local b0 = getHRP()
			b0 = b0 and b0.Position
			local moved = false
			local t0 = tick()
			while tick() - t0 < 30 and not cancelled do
				alive()
				pcall(function()
					game:GetService("ReplicatedStorage").Modules.Net
						:FindFirstChild("RF/SubmarineWorkerSpeak")
						:InvokeServer("TravelToSubmergedIsland")
				end)
				pcall(function()
					game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
				end)
				hold(0.2)
				local c0 = getHRP()
				if c0 and b0 and (c0.Position - b0).Magnitude > 500 then
					moved = true
					break
				end
			end
			dbg("TravelToSubmergedIsland dịch chuyển:", moved)
			return moved
		end
		if h.ent then
			local before = getHRP()
			before = before and before.Position
			local moved = false
			local attempt, t0 = 0, tick()
			while tick() - t0 < 30 and not cancelled do
				attempt = attempt + 1
				I()
				local ok, res = pcall(function()
					return game.ReplicatedStorage.Remotes.CommF_:InvokeServer("requestEntrance", h.ent)
				end)
				dbg("requestEntrance lần", attempt, h.ent, "ok=", ok, "res=", typeof(res), tostring(res))
				hold(0.2)
				local cur = getHRP()
				if cur and before and (cur.Position - before).Magnitude > 500 then
					moved = true
					break
				end
				dbg("chưa bị dịch chuyển, vị trí hiện tại", cur and cur.Position)
			end
			if not moved then
				dbg("requestEntrance KHÔNG dịch chuyển sau", attempt, "lần ->", h.to)
				return false
			end
		else
			if not jumpUntilNear(h.jump) then
				return false
			end
			hold(0.6)
		end
		local hrp = getHRP()
		if not hrp then
			return false
		end
		hrp.CFrame = hrp.CFrame + Vector3.new(0, LIFT, 0)
		local hub = nearestHub(hrp.Position)
		dbg("xong hop, đang ở", hub, "mong đợi", h.to, hrp.Position)
		return hub == h.to
	end

	function Sea3Gate.Cancel()
		cancelled = true
	end

	local function landingOf(h)
		if h.ent then
			return h.ent + V3(0, LIFT, 0)
		end
		local r = REFS[h.to]
		return r and r[1] or h.fly
	end
	local SUB_POCKET, SUB_NPC = V3(11538.6, -2154.7, 9827.3), V3(11427.9, -2156.4, 9726.2)
	local function routeFlyDist(pos, hops, targetPos, island)
		local cur, dist = pos, 0
		for _, key in ipairs(hops) do
			local h = HOP[key]
			dist = dist + (cur - h.fly).Magnitude
			cur = h.sub and SUB_POCKET or landingOf(h)
		end
		if island and SUB_ISLANDS[island] then
			dist = dist + (cur - SUB_NPC).Magnitude
			cur = SUB_ISLANDS[island]
		end
		return dist + (cur - targetPos).Magnitude
	end

	function Sea3Gate.Step(H, targetPos)
		if running then
			return true
		end
		if tick() < cool then
			return false
		end
		if (targetPos - Vector3.new(28282.5703125, 14896.8505859375, 105.1042709350586)).Magnitude <= 3000 then
			return false
		end
		local pos = H.Position
		local hops
		local island = getgenv().SubmarineDest(targetPos)
		if island then
			if nearestNode(pos, false) == island then
				why("player và đích cùng gần " .. island)
				return false
			end
			local ph = nearestHub(pos)
			hops = {}
			if ph ~= "Tiki" then
				if ph ~= "Castle" then
					hops[#hops + 1] = ph .. ">Castle"
				end
				hops[#hops + 1] = "Castle>Tiki"
			end
			hops[#hops + 1] = "Tiki>Submerged"
			dbg("tàu ngầm ->", island, "route", ph, table.concat(hops, " | "))
		else
			local dh = nearestOpenHub(targetPos)
			local ph = nearestHub(pos)
			if getgenv().DebugSea3 and nearestHub(targetPos) ~= dh then
				dbg("đích gần", nearestHub(targetPos), "nhưng cổng đang đóng -> dùng", dh)
			end
			if ph == dh then
				why("player và đích cùng gần đảo " .. ph)
				return false
			end
			hops = route(ph, dh)
			dbg("route", ph, "->", dh, table.concat(hops, " | "))
		end
		for _, key in ipairs(hops) do
			local need = HOP[key].need
			if need == "indra" and not getgenv().IsUnlocked("DefeatedIndraTrueForm") then
				why("Indra chưa mở (" .. key .. ")")
				return false
			end
			if need == "tiki" and not getgenv().IsTikiBossKilled() then
				why("boss Tiki chưa mở (" .. key .. "), raw=" .. tostring(getgenv().TikiBossRaw))
				return false
			end
		end

		do
			local direct = (pos - targetPos).Magnitude
			local viaFly = routeFlyDist(pos, hops, targetPos, island)
			local steps = #hops + (island and 1 or 0)
			local overheadSec = steps * (tonumber(getgenv().Sea3HopOverheadSec) or 0)
			if not getgenv().ShortcutWorth(direct, viaFly, overheadSec) then
				why(string.format("route %s dai hon bay thang (qua tele: bay %.0f + cho %.0fs >= thang %.0f) -> bay thang", table.concat(hops, " | "), viaFly, overheadSec, direct))
				return false
			end
			dbg(string.format("di duong tat loi hon: bay %.0f + cho %.0fs < thang %.0f", viaFly, overheadSec, direct))
		end

		running, cancelled = true, false
		getgenv().noclip = true
		local allOk = true
		for _, key in ipairs(hops) do
			local ok, res = pcall(runHop, HOP[key])
			if not (ok and res) then
				allOk = false
				break
			end
		end
		running = false

		dbg("kết quả chuỗi:", allOk)
		if allOk then
			fails = 0
		else
			fails = fails + 1
			if fails >= 2 then
				fails = 0
				cool = tick() + 30
			end
		end
		return true
	end
end

do
	local st = { pos = nil, tick = 0, running = false }

	local function screenOf(pos)
		local cam = workspace.CurrentCamera
		local v = cam:WorldToViewportPoint(pos)
		local vp = cam.ViewportSize
		if v.Z <= 0 or v.X < 0 or v.Y < 0 or v.X > vp.X or v.Y > vp.Y then
			cam.CFrame = CFrame.lookAt(cam.CFrame.Position, pos)
			v = cam:WorldToViewportPoint(pos)
		end
		local x = math.clamp(v.X, 1, vp.X - 1)
		local y = math.clamp(v.Y, 1, vp.Y - 1)
		if getgenv().ClickUseInset then
			y = y + game:GetService("GuiService"):GetGuiInset().Y
		end
		return x, y
	end

	getgenv().ClickWorldPos = function(pos)
		local now = tick()
		if now - (st.last or 0) < (getgenv().TreeClickInterval or 0.7) then
			return
		end
		st.last = now
		local x, y = screenOf(pos)
		if getgenv().DebugTreeClick then
			print("[TreeClick]", math.floor(x), math.floor(y))
		end
		local vim = game:GetService("VirtualInputManager")
		vim:SendMouseButtonEvent(x, y, 0, true, game, 1)
		vim:SendMouseButtonEvent(x, y, 0, false, game, 1)
	end
end

do
	local NPC = Vector3.new(3033, 2281, -7324)
	local running = false

	local function alive()
		k.LastCall = tick()
		getgenv().noclip = true
		I()
	end

	local function hold(t)
		local t0 = tick()
		while tick() - t0 < t do
			alive()
			task.wait(0.1)
		end
	end

	local function dbg(...)
		if getgenv().DebugTemple then
			print("[Temple]", ...)
		end
	end

	getgenv().EnterTempleOfTime = function(entry)
		if running then
			return
		end
		running = true
		pcall(function()
			local t0, arrived = tick(), false
			while tick() - t0 < 120 do
				local hrp = getHRP()
				if not hrp then
					return
				end
				if (hrp.Position - NPC).Magnitude < 15 then
					arrived = true
					break
				end
				alive()
				B(hrp, CFrame.new(NPC), tonumber(Settings["Speed Tween "]) or 190, 8)
				task.wait(0.15)
			end
			if not arrived then
				dbg("không bay tới được npc")
				return
			end
			BuddhaOffBeforeRemote(alive) -- tắt Phật trước khi RaceV4Progress Teleport
			BorrowTempleOfTime()
			hold(0.3)
			local inside = false
			local attempt, tStart = 0, tick()
			while tick() - tStart < 30 do
				attempt = attempt + 1
				BorrowTempleOfTime()
				I()
				local ok, res = pcall(function()
					return game.ReplicatedStorage.Remotes.CommF_:InvokeServer("RaceV4Progress", "Teleport")
				end)
				dbg("RaceV4Progress Teleport lần", attempt, "ok=", ok, "res=", typeof(res), tostring(res))
				hold(0.2)
				local cur = getHRP()
				if cur and (cur.Position - entry).Magnitude < 3000 then
					inside = true
					break
				end
			end
			if not inside then
				dbg("RaceV4Progress Teleport không đưa được vào đền")
				return
			end
			local hrp = getHRP()
			if hrp then
				hrp.CFrame = hrp.CFrame + Vector3.new(0, 30, 0)
			end
			dbg("đã vào đền")
		end)
		running = false
	end
end

do
	local cache, last = {}, {}
	getgenv().IsUnlocked = function(flag)
		if cache[flag] then
			return true
		end
		if tick() - (last[flag] or 0) < 10 then
			return false
		end
		last[flag] = tick()
		local ok, res = pcall(function()
			return game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("GetUnlockables")
		end)
		if getgenv().DebugUnlock then
			print("[Unlock]", flag, ok, typeof(res), type(res) == "table" and tostring(res[flag]) or "-")
		end
		if ok and type(res) == "table" and res[flag] then
			cache[flag] = true
		end
		return cache[flag] == true
	end
end

do
	local cache, lastAsk = false, 0
	getgenv().IsTikiBossKilled = function()
		if cache then
			return true
		end
		if tick() - lastAsk < 5 then
			return false
		end
		lastAsk = tick()
		local ok, res = pcall(function()
			local ev = game:GetService("ReplicatedStorage").Modules.Net:FindFirstChild("RF/SubmarineWorkerSpeak")
			return ev and ev:InvokeServer("AskKilledTikiBoss")
		end)
		getgenv().TikiBossRaw = res
		if getgenv().DebugTikiBoss then
			print("[TikiBoss]", ok, typeof(res), tostring(res))
		end
		if ok and res == true then
			cache = true
		end
		return cache
	end
end

