getgenv().getBladeHits = function(self, origins, radius, includePlayers)
	local V = {}
	local now = tick()
	local k = includePlayers and 2 or 1
	local ec = getgenv().__FA_Enemies
	if not ec then
		ec = { t = { 0, 0 }, l = {} }
		getgenv().__FA_Enemies = ec
	end
	local list = ec.l[k]
	if not list or now - ec.t[k] > 0.2 then
		list = Q(includePlayers)
		ec.l[k], ec.t[k] = list, now
	end
	radius = radius * (tonumber(getgenv().FastAttackRange) or 1)
	local origin = origins[1].Position
	for i = 1, #list do
		local y = list[i]
		if y ~= self and y.Parent and y:IsDescendantOf(Workspace) then
			local hrp = y:FindFirstChild("HumanoidRootPart")
			if hrp then
				local r = S:GetPlayerFromCharacter(y) and radius / 1.5 or radius
				local reach = 10 + r + hrp.Size.X / 2
				local pts = { hrp.Position }
				if hrp.Size.Y > 5 then
					table.insert(pts, (hrp.CFrame * CFrame.new(0, -hrp.Size.Y * 1.5 + 3, 0)).Position)
				end
				for j = 1, #pts do
					if (pts[j] - origin).Magnitude < reach then
						local parts = m(y, origin, r + hrp.Size.X / 2)
						for q = 1, #parts do
							V[#V + 1] = parts[q]
						end
						break
					end
				end
			end
		end
	end
	return V
end
local m = {
	RightUpperArm = true,
	RightLowerArm = true,
	RightHand = true,
	RightUpperLeg = true,
	RightLowerLeg = true,
	RightFoot = true,
	LeftUpperArm = true,
	LeftLowerArm = true,
