-- fallback: lay phan than cua quai dang farm de danh thang khi AOE khong quet thay (mot so bai quai bi mat muc tieu)
function __ForcedPart(mob, hrp, maxd)
	if not (mob and mob.Parent) or mob == game.Players.LocalPlayer.Character then
		return nil
	end
	local hum = mob:FindFirstChildOfClass("Humanoid")
	if hum and hum.Health <= 0 then
		return nil
	end
	local part = mob:FindFirstChild("UpperTorso") or mob:FindFirstChild("HumanoidRootPart") or mob:FindFirstChild("Head")
	if not (part and part:IsA("BasePart")) then
		return nil
	end
	if (part.Position - hrp.Position).Magnitude > maxd then
		return nil
	end
	return part
end
function __FastHit(radius, includePlayers, forced)
	local ch = t.Character
	if not ch then
		return
	end
	local stun = ch:FindFirstChild("Stun")
	if stun and stun.Value ~= 0 then
		return
	end
	local hrp = ch:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end
	local now = tick()
	-- gioi han toc do gui remote (token bucket) de khong lag
	local bk = getgenv().__FA_Bucket
	if not bk then
		bk = { n = 0, t = now }
		getgenv().__FA_Bucket = bk
	end
	local rate = tonumber(getgenv().FastAttackRate) or 150
	bk.n = math.min(bk.n + (now - bk.t) * rate, math.max(rate * 0.1, 6))
	bk.t = now
	if bk.n < 1 then
		return
	end
	local c = getgenv().__FA_Cache
	if not c then
		c = { t = 0 }
		getgenv().__FA_Cache = c
	end
	-- quet + sap xep muc tieu chi 1 lan moi ~0.06s, cac luong dung chung ket qua
	if not (c.sorted and c.r == radius and c.p == includePlayers and now - c.t < 0.06) then
		local list = AttackAOE(radius, includePlayers)
		local sorted = {}
		if list then
			for i = 1, #list do
				local e = list[i]
				local part = e and e[2]
				if part and part.Parent then
					sorted[#sorted + 1] = { (part.Position - hrp.Position).Magnitude, e }
				end
			end
			table.sort(sorted, function(a, b)
				return a[1] < b[1]
			end)
		end
		local rest = {}
		for i = 2, math.min(#sorted, 40) do
			rest[#rest + 1] = sorted[i][2]
		end
		c.sorted, c.rest, c.r, c.p, c.t = sorted, rest, radius, includePlayers, now
	end
	local first = c.sorted[1]
	local primary = first and first[2][2]
	local dist = primary and primary.Parent and (primary.Position - hrp.Position).Magnitude
	local maxd = tonumber(getgenv().FastAttackMaxDist) or math.max(75, (FarmH() or 0) + 40)
	local rest = c.rest
	local viaForced = false
	if not dist or dist > maxd then
		-- khong co muc tieu trong tam: ep lam moi + bo mo neo de bay lai gan quai
		if primary and not primary.Parent then
			c.t = 0
		end
		local ms = getgenv().__FA_Miss
		if not ms then
			getgenv().__FA_Miss = now
		elseif now - ms > 0.4 then
			getgenv().__HoldAnchor = nil
			c.t = 0
		end
		-- van danh thang vao quai dang farm neu no du gan (tranh bai quai khong an don)
		local fp = forced and __ForcedPart(forced, hrp, maxd + 60)
		if not fp then
			return
		end
		primary, rest, dist, viaForced = fp, {}, (fp.Position - hrp.Position).Magnitude, true
	end
	if not viaForced then
		getgenv().__FA_Miss = nil
	end
	if getgenv().FastAttackDebug and now - (getgenv().__FA_DbgT or 0) > 1 then
		getgenv().__FA_DbgT = now
		print("[FastAttack] muc tieu:", #c.sorted, "gan nhat:", math.floor(dist), "stud")
	end
	local burst = math.min(math.clamp(math.floor(getgenv().FastAttackBurst), 1, 12), math.floor(bk.n))
	bk.n = bk.n - burst
	for _ = 1, burst do
		E:FireServer(0)
		l:FireServer(primary, rest)
	end
end
