function __SpawnFAWorkers()
	getgenv().__FA_Gen = (getgenv().__FA_Gen or 0) + 1
	local gen = getgenv().__FA_Gen
	getgenv().__FA_Beat = tick()
	for idx = 1, 4 do
		task.spawn(function()
			local last = 0
			local RS = game:GetService("RunService")
			local sig = ({ RS.Heartbeat, RS.Stepped, RS.RenderStepped, RS.Heartbeat })[idx]
			while getgenv().__FA_Gen == gen do
				sig:Wait()
				local now = tick()
				if idx == 1 then
					getgenv().__FA_Beat = now
				end
				local st = getgenv().__FA
				if idx <= (getgenv().FastAttackWorkers or 2) and st and st.fn and now - st.t < 0.3 and now - last >= (tonumber(getgenv().FastAttackDelay) or 0.001) then
					last = now
					pcall(st.fn)
				end
			end
		end)
	end
end
