do
	local TR = {
		Range = 60,
		HoldTime = 0.01,
		Vec = Vector3.new(0.01, -0.8, 0.01),
		Delay = 0.15,
		MinDelay = 0.05,
		MaxDelay = 1.5,
		Id = 0,
		S = 0,
		D = 0,
		WinStart = 0,
		MonT = 0,
		LastPulse = 0,
		Last = setmetatable({}, { __mode = "k" }),
		HumCache = setmetatable({}, { __mode = "k" }),
		Conn = nil,
	}
	TR.Plr = game:GetService("Players").LocalPlayer

	function TR.Root()
		local c = TR.Plr.Character
		return c and c:FindFirstChild("HumanoidRootPart")
	end

	-- lay fruit bat ky dang cam/co (ToolTip == "Blox Fruit"), uu tien cai dang cam tren tay
	function TR.GetFruit()
		local c = TR.Plr.Character
		if c then
			for _, tool in ipairs(c:GetChildren()) do
				if tool:IsA("Tool") and tool.ToolTip == "Blox Fruit" then
					return tool
				end
			end
		end
		local bp = TR.Plr:FindFirstChild("Backpack")
		if bp then
			for _, tool in ipairs(bp:GetChildren()) do
				if tool:IsA("Tool") and tool.ToolTip == "Blox Fruit" then
					return tool
				end
			end
		end
		return nil
	end

	-- mob song gan nhat trong tam, tra ve huong ngang tu minh toi mob
	function TR.AimDir()
		local root, enemies = TR.Root(), workspace:FindFirstChild("Enemies")
		if not (root and enemies) then
			return nil
		end
		local best, bestD
		for _, mob in ipairs(enemies:GetChildren()) do
			local mr = mob:FindFirstChild("HumanoidRootPart")
			local hum = mr and TR.GetHum(mob)
			if hum and hum.Health > 0 then
				local d = (mr.Position - root.Position).Magnitude
				if d <= TR.Range and (not bestD or d < bestD) then
					best, bestD = mr, d
				end
			end
		end
		if not best then
			return nil
		end
		local flat = (best.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude < 0.01 then
			return TR.Vec
		end
		return flat.Unit
	end

	function TR.GetHum(mob)
		local h = TR.HumCache[mob]
		if not h or h.Parent ~= mob then
			h = mob:FindFirstChildOfClass("Humanoid")
			TR.HumCache[mob] = h
		end
		return h
	end

	function TR.HasTarget()
		local root, enemies = TR.Root(), workspace:FindFirstChild("Enemies")
		if not (root and enemies) then
			return false
		end
		for _, mob in ipairs(enemies:GetChildren()) do
			local mr = mob:FindFirstChild("HumanoidRootPart")
			local hum = mr and TR.GetHum(mob)
			if hum and hum.Health > 0 and (mr.Position - root.Position).Magnitude <= TR.Range then
				return true
			end
		end
		return false
	end

	-- đếm "xung sát thương": mỗi lần có mob trong tầm bị trừ máu (gộp trong 0.04s) = 1 xung server đã nhận
	function TR.Monitor()
		local now = tick()
		if now - TR.MonT < 0.03 then
			return
		end
		TR.MonT = now
		local root, enemies = TR.Root(), workspace:FindFirstChild("Enemies")
		if not (root and enemies) then
			return
		end
		local pulse = false
		for _, mob in ipairs(enemies:GetChildren()) do
			local mr = mob:FindFirstChild("HumanoidRootPart")
			local hum = mr and TR.GetHum(mob)
			if hum and (mr.Position - root.Position).Magnitude <= TR.Range + 10 then
				local hp = hum.Health
				local last = TR.Last[hum]
				if last and hp < last - 0.001 then
					pulse = true
				end
				TR.Last[hum] = hp
			end
		end
		if pulse and now - TR.LastPulse > 0.04 then
			TR.LastPulse = now
			TR.D = TR.D + 1
		end
	end

	function TR.Fire()
		local fruit = TR.GetFruit()
		if not fruit then
			return false
		end
		if not TR.HasTarget() then
			return false
		end
		local remote = fruit:FindFirstChild("LeftClickRemote")
		if remote then
			remote:FireServer(TR.AimDir() or TR.Vec, 1)
			task.wait(TR.HoldTime)
			remote:FireServer(false)
			return true
		end
		-- fruit khong co LeftClickRemote (kieu TAP)
		local rf, re = fruit:FindFirstChild("RemoteFunction"), fruit:FindFirstChild("RemoteEvent")
		if rf then
			if re then
				local root = TR.Root()
				local dir = TR.AimDir()
				re:FireServer(root and dir and (root.Position + dir * 10) or nil)
			end
			rf:InvokeServer("TAP")
			return true
		end
		return false
	end

	-- chỉnh delay theo tỉ lệ (xung server nhận / phát bắn) trong mỗi cửa sổ 1s
	function TR.Tune()
		local now = tick()
		if now - TR.WinStart < 1 then
			return
		end
		local S, D = TR.S, TR.D
		TR.WinStart, TR.S, TR.D = now, 0, 0
		if S < 3 or D == 0 then
			return
		end
		local ratio = D / S
		if ratio >= 0.85 then
			TR.Delay = math.max(TR.MinDelay, TR.Delay * 0.85)
		elseif ratio < 0.6 then
			TR.Delay = math.min(TR.MaxDelay, TR.Delay * math.clamp(0.75 / ratio, 1.1, 1.5))
		end
	end

	function TR.Stop()
		TR.Id = TR.Id + 1
		if TR.Conn then
			TR.Conn:Disconnect()
			TR.Conn = nil
		end
	end

	function TR.Start()
		TR.Stop()
		local myId = TR.Id
		TR.Delay, TR.S, TR.D, TR.WinStart = 0.15, 0, 0, tick()
		TR.Conn = getgenv().__BF_Track(game:GetService("RunService").Heartbeat:Connect(function()
			pcall(TR.Monitor)
		end))
		task.spawn(function()
			while Settings["Aura T-rex"] and TR.Id == myId do
				local ok, fired = pcall(TR.Fire)
				if ok and fired then
					TR.S = TR.S + 1
				end
				pcall(TR.Tune)
				task.wait(TR.Delay)
			end
			if TR.Id == myId and TR.Conn then
				TR.Conn:Disconnect()
				TR.Conn = nil
			end
		end)
	end

	SettingFarmMainSection.CreateToggle(
		{ Title = "Aura Fruit", Desc = "Auto M1 fruit dang co (moi loai fruit)", Default = Settings["Aura T-rex"] or false },
		function(I)
			SaveSettings("Aura T-rex", I)
			if I then
				TR.Start()
			else
				TR.Stop()
			end
		end
	)
end
