		f = (function() if string.find(V.Name, "Fruit") then return V.Name else return f end end)()
	end
	for V, V in pairs(t.Character:GetChildren()) do
		f = (function() if string.find(V.Name, "Fruit") then return V.Name else return f end end)()
	end
