local function ClickCardButton(btn)
	for _, sig in ipairs({ "Activated", "MouseButton1Click", "MouseButton1Down", "MouseButton1Up" }) do
		local ok, conns = pcall(getconnections, btn[sig])
		if ok and conns and #conns > 0 then
			for _, c in ipairs(conns) do
				pcall(function()
					if c.Function then
						c.Function()
					else
						c:Fire()
					end
				end)
			end
			return true
		end
	end
	if firesignal then
		local ok = pcall(firesignal, btn.Activated)
		if ok then
			return true
		end
		ok = pcall(firesignal, btn.MouseButton1Click)
		return ok
	end
	return false
end
function GetDungeonCards()
	local cards, seen = {}, {}
	local pg = t:FindFirstChild("PlayerGui")
	if not pg then
		return cards
	end
	for _, lbl in ipairs(pg:GetDescendants()) do
		if lbl.Name == "DisplayName" and lbl:IsA("TextLabel") and lbl.Visible and lbl.Text ~= "" then
			local key = DisplayNameToKey[stripFont(lbl.Text)]
			if key then
				local node, btn = lbl.Parent, nil
				for _ = 1, 8 do
					if not node or node == pg then
						break
					end
					if node:FindFirstChild("BuffDescription", true) then
						local count = 0
						for _, d in ipairs(node:GetDescendants()) do
							if d.Name == "DisplayName" and d:IsA("TextLabel") then
								count = count + 1
							end
						end
						if count == 1 then
							btn = node:IsA("GuiButton") and node or node:FindFirstChildWhichIsA("GuiButton", true)
							if btn then
								break
							end
						end
					end
					node = node.Parent
				end
				if btn and not seen[btn] then
					seen[btn] = true
					cards[#cards + 1] = { key = key, btn = btn }
				end
			end
		end
	end
	return cards
end
function AutoPickDungeonCard()
	local prio = Settings["Select Card Priority"] or {}
	local rank = {}
	for i, name in ipairs(prio) do
		local key = DisplayNameToKey[name]
		if key and not rank[key] then
			rank[key] = i
		end
	end
	local cards = GetDungeonCards()
	if #cards == 0 then
		return false
	end
	local best, bestRank = nil, math.huge
	for _, c in ipairs(cards) do
		local r = rank[c.key]
		if r and r < bestRank then
			best, bestRank = c, r
		end
	end
	if best then
		print("AUTO PICK (PRIORITY INDEX):", bestRank, best.key)
	else
		best = cards[math.random(1, #cards)]
		print("AUTO PICK (RANDOM):", best.key)
	end
	return ClickCardButton(best.btn)
end
DungeonSection.CreateToggle(
	{
		Title = "Auto Attack Dungeon",
		Desc = "Auto Attack Mob and go next Floor",
		Default = Settings["Auto Attack Dungeon"] or false,
	},
	function(b)
		SaveSettings("Auto Attack Dungeon", b)
		if not b then
			return
		end
		task.spawn(function()
			while Settings["Auto Attack Dungeon"] do
				task.wait()
				local b, b = pcall(function()
					if t.Character.Humanoid.Health <= 0 then
						return
					end
					local E, l = GetCurrentFloor(), GetHightFloor()
					if not E or not l then
						return
					end
					if E ~= l then
						getgenv().AutoDungeonNextFloor = true
						local y = l - 1
						local P = workspace.Map.Dungeon:FindFirstChild(tostring(y))
						if
							P
							and (P:FindFirstChild("ExitTeleporter"))
							and (P.ExitTeleporter:FindFirstChild("Root"))
							and (P.ExitTeleporter.Root:FindFirstChild("TouchInterest"))
						then
							if t:DistanceFromCharacter(P.ExitTeleporter.Root.Position) > 15 then
								task.wait(1)
								toTarget(P.ExitTeleporter.Root.CFrame * CFrame.new(0, 5, 0))
							else
								task.wait(3)
							end
						end
						return
					end
					if getgenv().AutoDungeonNextFloor then
						TweenManager.CancelCurrent()
						getgenv().AutoDungeonNextFloor = false
					end
					l, E = DetectMobDungeon(), DetectPropHitboxPlaceholder()
					if not l or not IsMobAlive(l) then
						return
					end
					if E then
						repeat
							task.wait()
							if not Settings["Auto Attack Dungeon"] then
								break
							end
							if not IsMobAlive(E) then
								break
							end
							if not GetCurrentFloor() or GetCurrentFloor() ~= GetHightFloor() then
								break
							end
							local y = Settings["Select Weapon Dungeon"] or "Melee"
							equiptool(NameWeapon(y))
							if y == "Gun" then
								if NameWeapon(y) == "Dragonstorm" then
									SpamGunDragonStorm(E.HumanoidRootPart)
								else
									ShootM1(E)
								end
							else
								ClickM1Dungeon(E)
							end
							sizepart(E)
							if y == "Blox Fruit" then
								toTarget(FarmCF(E.HumanoidRootPart, FruitFarmY()))
							else
								toTarget(FarmCF(E.HumanoidRootPart, BuddhaFarmY()))
							end
						until t.Character.Humanoid.Health <= 0
					else
						repeat
							task.wait()
							if not Settings["Auto Attack Dungeon"] then
								break
							end
							if not IsMobAlive(l) then
								break
							end
							if not GetCurrentFloor() or GetCurrentFloor() ~= GetHightFloor() then
								break
							end
							local E = Settings["Select Weapon Dungeon"] or "Melee"
							equiptool(NameWeapon(E))
							if E == "Gun" then
								if NameWeapon(E) == "Dragonstorm" then
									SpamGunDragonStorm(l.HumanoidRootPart)
								else
									ShootM1(l)
								end
							else
								ClickM1Dungeon(l)
							end
							sizepart(l)
							BringMob(l)
							if E == "Blox Fruit" then
								toTarget(FarmCF(l.HumanoidRootPart, FruitFarmY()))
							else
								toTarget(FarmCF(l.HumanoidRootPart, BuddhaFarmY()))
							end
						until t.Character.Humanoid.Health <= 0 or (DetectPropHitboxPlaceholder())
					end
				end)
				if b then
					warn("[Auto Dungeon Error]:", b)
				end
			end
		end)
	end
)
