	if game.workspace.Map:FindFirstChild("MysticIsland") then
		for m, m in pairs(game.workspace.Map.MysticIsland:GetChildren()) do
			if m:IsA("MeshPart") and m.MeshId == "rbxassetid://10153114969" then
