end
function getHighestPoint()
	if not game.workspace.Map:FindFirstChild("MysticIsland") then
		return nil
	end
	for m, m in pairs(game:GetService("Workspace").Map.MysticIsland:GetDescendants()) do
		if m:IsA("MeshPart") then
