function CheckAbility()
	local l, S, I = next, game.Players.LocalPlayer.Backpack:GetChildren()
	for _, _ in l, S, I do
		if table.find(m, _.Name) then
			return true
		end
	end
	l, S, I = next, game.Players.LocalPlayer.Character:GetChildren()
	for _, _ in l, S, I do
		if table.find(m, _.Name) then
			return true
		end
	end
