function VerifyNearbyTrial()
	local g, R, m, l =
		{
			"Trial of the Machine",
			"Trial of Speed",
			"Trial of Strength",
			"Trial of Water",
			"Trial of the King",
			"Trial of Carnage",
			"Trial of Flames",
		},
		next,
		workspace._WorldOrigin.Locations:GetChildren()
	for S, S in R, m, l do
		if table.find(g, S.Name) and t:DistanceFromCharacter(S.Position) < 1500 then
			return true
