function DetectQuestRainBowHaki(R)
	if not R then
		for R, R in next, g, nil do
			if
				HasQuest()
				and (QuestHas(R))
			then
				return false
			end
		end
		for R, R in next, g, nil do
			if
				not QuestHas(R)
				or not HasQuest()
			then
				return true
			end
		end
	else
		for R, R in next, g, nil do
			if QuestHas(R) then
				return R
			end
		end
	end
end
