						end
					else
						print("delete")
						for g, g in pairs(game:GetService("Workspace")._WorldOrigin.PlayerSpawns.Pirates:GetChildren()) do
							if g:FindFirstChild("Ignored") then
								g:FindFirstChild("Ignored"):Destroy()
