				end
			end
		else
			game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("TravelDressrosa")
		end
	else
		local g, R, m = DetectRequestSoulGuitar()
		if game.PlaceId == R then
			local R = DetectMob(g)
			if R then
				repeat
					task.wait()
					sizepart(R)
					BringMob(R)
