						local R = DetectPartSpawnMob(DetectNameTablePart(g))
						if R then
							table.insert(N, DetectNameTablePart(g))
							repeat
								wait()
								toTarget(R.CFrame * CFrame.new(0, 60, 0))
							until (R.Position - t.Character.HumanoidRootPart.Position).Magnitude <= 100
								or (DetectMob(g))
