			["Venom Fruit"] = Color3.fromRGB(180, 60, 200),
			["Dough Fruit"] = Color3.fromRGB(255, 220, 180),
			["Light Fruit"] = Color3.fromRGB(255, 255, 150),
		})[s] or (Color3.fromRGB(255, 255, 255)),
		Drawing.new("Text")
	f.Visible = false
	f.Transparency = 1
	f.Text = s
	f.Color = g
	f.Size = 20
	f.Outline = true
	f.OutlineColor = Color3.fromRGB(0, 0, 0)
