	spawn(function()
		repeat
			task.wait()
			if X then
				local m, E = workspace.CurrentCamera:WorldToViewportPoint(X.Position)
				if E then
					f.Text = s .. " [" .. math.round(t:DistanceFromCharacter(X.Position)) .. "m]"
					f.Position = Vector2.new(m.X, m.Y - 20)
					f.Color = g
					f.Visible = true
