-- ============================ ANTI LAG PRIME ============================
;(function()
	local Lighting = game:GetService("Lighting")
	local RunSvc = game:GetService("RunService")
	local lp = game:GetService("Players").LocalPlayer
	local AL = getgenv().WindyAntiLag
	if AL and AL.stop then pcall(AL.stop) end
	if AL and AL.guardConn then pcall(function() AL.guardConn:Disconnect() end) end
	AL = { on = false, conns = {}, saved = nil, queue = {}, qh = 1, qt = 0, sweep = nil, fx = {}, cleaned = 0 }
	getgenv().WindyAntiLag = AL

	local LEVELS = { ["Light (Nhẹ)"] = 1, ["Strong (Mạnh)"] = 2, ["Prime (Siêu Mạnh)"] = 3 }
	local function lvl() return LEVELS[Settings["Anti Lag Level"] or "Prime (Siêu Mạnh)"] or 3 end
	local function say(t, k, h) pcall(function() if getgenv().WindyStatus then getgenv().WindyStatus(t, k or "info", h or 4) end end) end

	local PostFx = { "BlurEffect", "SunRaysEffect", "ColorCorrectionEffect", "BloomEffect", "DepthOfFieldEffect" }
	local function isPostFx(o)
		for _, c in ipairs(PostFx) do if o:IsA(c) then return true end end
		return false
	end

	local function cleanFx(o) -- hieu ung: tat ngay (re), goi truc tiep tu event
		if o:IsA("ParticleEmitter") then
			if o.Parent and o.Parent.Name == "RelicFire" then return true end
			o.Enabled = false o.Rate = 0 o.Lifetime = NumberRange.new(0) return true
		elseif o:IsA("Trail") or o:IsA("Beam") or o:IsA("Fire") or o:IsA("Smoke") or o:IsA("Sparkles") then
			o.Enabled = false return true
		elseif o:IsA("PointLight") or o:IsA("SpotLight") or o:IsA("SurfaceLight") then
			o.Enabled = false return true
		elseif o:IsA("Explosion") then
			o.Visible = false o.BlastPressure = 0 o.BlastRadius = 1 return true
		end
		return false
	end
	local function cleanHeavy(o, level) -- part/decal/mesh: lam qua hang doi co gioi han thoi gian
		if o:IsA("BasePart") then
			if level >= 2 then
				local par = o.Parent
				if not (par and par:FindFirstChildOfClass("Humanoid")) then
					o.Material = Enum.Material.SmoothPlastic o.Reflectance = 0
				end
				o.CastShadow = false
				if level >= 3 and o:IsA("MeshPart") and o.TextureID ~= "" then o.TextureID = "" end
			end
		elseif level >= 2 and (o:IsA("Decal") or o:IsA("Texture")) then
			local ch = lp.Character
			if not (ch and o:IsDescendantOf(ch)) then o.Transparency = 1 end
		elseif level >= 3 and o:IsA("SurfaceAppearance") then
			o:Destroy()
		elseif level >= 3 and (o:IsA("Accessory") or o:IsA("Clothing") or o:IsA("ShirtGraphic") or o:IsA("CharacterMesh")) then
			local ch = lp.Character
			if not (ch and o:IsDescendantOf(ch)) then o:Destroy() end
		end
	end
	local function clean(o, level)
		pcall(function()
			if not cleanFx(o) then cleanHeavy(o, level) end
			AL.cleaned = AL.cleaned + 1
		end)
	end

	local function snapshot()
		local s = { ql = nil, shadows = Lighting.GlobalShadows, fogEnd = Lighting.FogEnd, fogStart = Lighting.FogStart, diffuse = nil, specular = nil, atm = {}, terr = {} }
		pcall(function() s.ql = settings().Rendering.QualityLevel end)
		pcall(function() s.diffuse, s.specular = Lighting.EnvironmentDiffuseScale, Lighting.EnvironmentSpecularScale end)
		local t = workspace:FindFirstChildOfClass("Terrain")
		if t then s.terr = { WaterWaveSize = t.WaterWaveSize, WaterWaveSpeed = t.WaterWaveSpeed, WaterReflectance = t.WaterReflectance } end
		return s
	end
	local function applyGlobal()
		pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
		pcall(function() settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04 end)
		pcall(function() UserSettings():GetService("UserGameSettings").SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1 end)
		pcall(function()
			Lighting.GlobalShadows = false
			Lighting.FogEnd = 9e9
			Lighting.FogStart = 9e9
			Lighting.EnvironmentDiffuseScale = 0
			Lighting.EnvironmentSpecularScale = 0
		end)
		pcall(function() sethiddenproperty(Lighting, "Technology", Enum.Technology.Compatibility) end)
		local t = workspace:FindFirstChildOfClass("Terrain")
		if t then
			pcall(function()
				t.WaterWaveSize = 0 t.WaterWaveSpeed = 0 t.WaterReflectance = 0
				sethiddenproperty(t, "Decoration", false)
			end)
		end
		for _, o in ipairs(Lighting:GetChildren()) do
			if isPostFx(o) and o.Name ~= "WindyBlur" and o.Enabled then
				AL.fx[#AL.fx + 1] = o
				pcall(function() o.Enabled = false end)
			elseif o:IsA("Atmosphere") and o.Density > 0 then
				AL.saved.atm[o] = { o.Density, o.Haze, o.Glare }
				pcall(function() o.Density = 0 o.Haze = 0 o.Glare = 0 end)
			end
		end
	end
	local function restoreGlobal()
		local s = AL.saved
		if not s then return end
		pcall(function() if s.ql then settings().Rendering.QualityLevel = s.ql end end)
		pcall(function()
			Lighting.GlobalShadows = s.shadows Lighting.FogEnd = s.fogEnd Lighting.FogStart = s.fogStart
			if s.diffuse then Lighting.EnvironmentDiffuseScale = s.diffuse Lighting.EnvironmentSpecularScale = s.specular end
		end)
		pcall(function() sethiddenproperty(Lighting, "Technology", Enum.Technology.ShadowMap) end)
		local t = workspace:FindFirstChildOfClass("Terrain")
		if t and s.terr.WaterWaveSize then
			pcall(function()
				t.WaterWaveSize = s.terr.WaterWaveSize t.WaterWaveSpeed = s.terr.WaterWaveSpeed t.WaterReflectance = s.terr.WaterReflectance
				sethiddenproperty(t, "Decoration", true)
			end)
		end
		for _, o in ipairs(AL.fx) do pcall(function() if o.Parent then o.Enabled = true end end) end
		AL.fx = {}
		for o, v in pairs(s.atm) do pcall(function() if o.Parent then o.Density, o.Haze, o.Glare = v[1], v[2], v[3] end end) end
	end

	local function startSweep()
		local list = {}
		pcall(function() list = workspace:GetDescendants() end)
		AL.sweep = { list = list, i = 1 }
		AL.cleaned = 0
	end
	local function onAdded(o)
		if not AL.on then return end
		pcall(cleanFx, o)
		if o:IsA("BasePart") or o:IsA("Decal") or o:IsA("Texture") or o:IsA("SurfaceAppearance") or o:IsA("Accessory") or o:IsA("Clothing") or o:IsA("ShirtGraphic") then
			AL.qt = AL.qt + 1
			AL.queue[AL.qt] = o
		end
	end

	function AL.start()
		if AL.on then return end
		AL.on = true
		AL.saved = AL.saved or snapshot()
		pcall(applyGlobal)
		AL.conns[#AL.conns + 1] = workspace.DescendantAdded:Connect(onAdded)
		AL.conns[#AL.conns + 1] = Lighting.ChildAdded:Connect(function(o)
			if not AL.on then return end
			task.defer(function()
				pcall(function()
					if isPostFx(o) and o.Name ~= "WindyBlur" then AL.fx[#AL.fx + 1] = o o.Enabled = false end
				end)
			end)
		end)
		AL.conns[#AL.conns + 1] = RunSvc.Heartbeat:Connect(function()
			if not AL.on then return end
			local t0, level = os.clock(), lvl()
			-- hang doi vat the moi (uu tien), toi da ~3ms moi frame
			while AL.qh <= AL.qt do
				local o = AL.queue[AL.qh]
				AL.queue[AL.qh] = nil
				AL.qh = AL.qh + 1
				if o and o.Parent then clean(o, level) end
				if os.clock() - t0 > 0.003 then break end
			end
			if AL.qh > AL.qt then AL.qh, AL.qt = 1, 0 end
			-- quet toan map, chia nho tung frame de khong dung hinh
			local sw = AL.sweep
			if sw and os.clock() - t0 < 0.005 then
				local list = sw.list
				while sw.i <= #list do
					local o = list[sw.i]
					list[sw.i] = false
					sw.i = sw.i + 1
					if o and o.Parent then clean(o, level) end
					if os.clock() - t0 > 0.006 then break end
				end
				if sw.i > #list then
					AL.sweep = nil
					say("Anti Lag Prime • đã tối ưu " .. AL.cleaned .. " vật thể", "ok", 5)
				end
			end
		end)
		startSweep()
		say("Anti Lag Prime • đã bật (" .. tostring(Settings["Anti Lag Level"] or "Prime (Siêu Mạnh)") .. ")", "ok", 4)
	end
	function AL.stop()
		if not AL.on then return end
		AL.on = false
		for _, c in ipairs(AL.conns) do pcall(function() c:Disconnect() end) end
		AL.conns = {}
		AL.queue, AL.qh, AL.qt, AL.sweep = {}, 1, 0, nil
		restoreGlobal()
		say("Anti Lag Prime • đã tắt (vào lại server để trả đồ hoạ map)", "warn", 5)
	end

	local AntiLagSection = SettingPage.CreateSection("Anti Lag Prime")
	AntiLagSection.CreateToggle({
		Title = "Anti Lag Prime",
		Desc = "Tăng FPS siêu mạnh: tắt hiệu ứng skill, bóng, sương, texture, ánh sáng nặng; tự dọn vật thể mới sinh ra.",
		Default = Settings["Anti Lag Prime"] or false,
	}, function(v)
		SaveSettings("Anti Lag Prime", v)
		if v then AL.start() else AL.stop() end
	end)
	AntiLagSection.CreateDropdown({
		Title = "Anti Lag Level",
		List = { "Light (Nhẹ)", "Strong (Mạnh)", "Prime (Siêu Mạnh)" },
		Search = false,
		Selected = false,
		Default = Settings["Anti Lag Level"] or "Prime (Siêu Mạnh)",
	}, function(v)
		SaveSettings("Anti Lag Level", v)
		if AL.on then startSweep() end
	end)
	AntiLagSection.CreateButton({ Title = "Clean Lag Now" }, function()
		if AL.on then startSweep() else AL.start() end
		pcall(function() collectgarbage("collect") end)
	end)
	AntiLagSection.CreateToggle({
		Title = "Unlock FPS",
		Desc = "Bỏ giới hạn 60 FPS (nếu executor hỗ trợ setfpscap).",
		Default = Settings["Unlock FPS"] or false,
	}, function(v)
		SaveSettings("Unlock FPS", v)
		pcall(function() if setfpscap then setfpscap(v and 9999 or 60) end end)
	end)
	AntiLagSection.CreateToggle({
		Title = "Smart Lag Guard",
		Desc = "Tự giảm tải khi FPS thấp: giảm tốc độ đánh nhanh + bật Anti Lag, FPS ổn lại thì trả về như cũ.",
		Default = Settings["Smart Lag Guard"] ~= false,
	}, function(v)
		SaveSettings("Smart Lag Guard", v)
	end)
	do
		local fpsAvg = 60
		AL.guardConn = RunSvc.Heartbeat:Connect(function(dt)
			fpsAvg = fpsAvg + (1 / math.max(dt, 1 / 240) - fpsAvg) * 0.05
		end)
		local guard = { low = 0, high = 0, active = false, base = nil }
		task.spawn(function()
			local gcT = os.clock()
			while getgenv().WindyAntiLag == AL do
				task.wait(1)
				if Settings["Smart Lag Guard"] ~= false then
					if fpsAvg < 28 then
						guard.low, guard.high = guard.low + 1, 0
					elseif fpsAvg > 45 then
						guard.high, guard.low = guard.high + 1, 0
					else
						guard.low, guard.high = 0, 0
					end
					local g = getgenv()
					if not guard.active and guard.low >= 3 then
						guard.active = true
						guard.base = { w = g.FastAttackWorkers, b = g.FastAttackBurst, r = g.FastAttackRate, on = AL.on }
						g.FastAttackWorkers = 1
						g.FastAttackBurst = math.max(1, math.floor((tonumber(g.FastAttackBurst) or 3) / 2))
						g.FastAttackRate = math.max(60, math.floor((tonumber(g.FastAttackRate) or 150) / 2))
						if not AL.on then AL.start() end
						say("Smart Lag Guard • FPS thấp, đã giảm tải", "warn", 5)
					elseif guard.active and guard.high >= 8 then
						guard.active = false
						local b = guard.base
						if b then
							g.FastAttackWorkers, g.FastAttackBurst, g.FastAttackRate = b.w, b.b, b.r
							if not b.on then AL.stop() end
						end
						say("Smart Lag Guard • FPS đã ổn, trả lại như cũ", "ok", 4)
					end
				end
				-- don bo nho dinh ky khi dang chong lag
				if (AL.on or guard.active) and os.clock() - gcT > 45 then
					gcT = os.clock()
					pcall(function() collectgarbage("collect") end)
				end
			end
		end)
	end
	if Settings["Anti Lag Prime"] then task.defer(AL.start) end
	if Settings["Unlock FPS"] then pcall(function() if setfpscap then setfpscap(9999) end end) end
end)()
